    function updateUploadProgress(word, sub, progress) {
      const modal = document.getElementById('uploadConfirmationModal');
      const initPhase = document.getElementById('uploadConfirmInitialPhase');
      const stepperPhase = document.getElementById('uploadStepperProgressPhase');
      const wordEl = document.getElementById('stepperCurrentWord');
      const subEl = document.getElementById('stepperCurrentSub');
      const barEl = document.getElementById('stepperProgressBarFill');

      if (modal) modal.classList.add('active');
      if (initPhase) initPhase.style.display = 'none';
      if (stepperPhase) stepperPhase.style.display = 'block';

      if (wordEl) wordEl.textContent = word || 'Processando...';
      if (subEl) subEl.textContent = sub || 'MedTutor AI executando análise médica...';
      if (barEl) barEl.style.width = Math.min(100, Math.max(0, progress || 0)) + '%';
    }
    window.updateUploadProgress = updateUploadProgress;

    // Cada leitura local precisa ser observável: mantém a interface e o
    // terminal atualizados e encerra a espera caso uma biblioteca/arquivo
    // bloqueie a extração indefinidamente.
    async function runUploadStepWithFeedback(task, { fileName, label, progress = 20, timeoutMs = 35_000 }) {
      const startedAt = Date.now();
      let heartbeat = null;
      const emitHeartbeat = () => {
        const elapsed = Math.max(1, Math.round((Date.now() - startedAt) / 1000));
        updateUploadProgress('1. Lendo arquivo...', `${label} (${elapsed}s). O processamento continua ativo...`, progress);
        reportUploadDiagnostic({
          originalFileName: fileName,
          aiEngine: `Leitura local em andamento: ${label}`,
          uploadInputChars: 0,
          markdownText: '',
          clinicalImages: []
        }, 'processando');
      };
      heartbeat = setInterval(emitHeartbeat, 5_000);
      try {
        return await Promise.race([
          Promise.resolve().then(task),
          new Promise((_, reject) => setTimeout(() => reject(new Error(`Tempo limite de ${Math.round(timeoutMs / 1000)}s durante ${label}.`)), timeoutMs))
        ]);
      } finally {
        clearInterval(heartbeat);
      }
    }

