    function resetPvpSetup() {
      if (pvpBattleState.timerInterval) clearInterval(pvpBattleState.timerInterval);
      pvpBattleState.active = false;
      const setup = document.getElementById('pvpSetupScreen');
      const arena = document.getElementById('pvpArenaScreen');
      const result = document.getElementById('pvpResultScreen');
      if (setup) setup.style.display = 'flex';
      if (arena) arena.style.display = 'none';
      if (result) result.style.display = 'none';
    }

    function handlePvpModeChange(val) {
      const shareBox = document.getElementById('pvpPeerShareBox');
      const codeText = document.getElementById('pvpShareCodeText');
      if (!shareBox) return;
      if (val === 'peer') {
        shareBox.style.display = 'block';
        if (codeText) codeText.textContent = `MED-DUEL-${Math.floor(1000 + Math.random() * 9000)}`;
      } else {
        shareBox.style.display = 'none';
      }
    }

    function copyPvpShareCode() {
      const codeText = document.getElementById('pvpShareCodeText')?.textContent || 'MED-DUEL-8821';
      const link = `${window.location.origin || 'https://medtutor.app'}?duel=${codeText}`;
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(link).catch(() => {});
      }
      showToast(`📋 Link de desafio ${codeText} copiado para a área de transferência!`);
    }

    function startPvpBattle() {
      const discSelect = document.getElementById('pvpDisciplineSelect');
      const roundsSelect = document.getElementById('pvpRoundsSelect');
      const modeSelect = document.getElementById('pvpModeSelect');

      const discipline = (discSelect && discSelect.value) ? discSelect.value : (currentStudySubject || '5º Período - Cardiologia Clínica');
      const rounds = (roundsSelect && roundsSelect.value) ? (parseInt(roundsSelect.value, 10) || 5) : 5;
      const mode = (modeSelect && modeSelect.value) ? modeSelect.value : 'ai_resident';

      let questions = sharedQuestionsBank.filter(q => q.subject === discipline);
      if (questions.length < rounds) {
        const extra = sharedQuestionsBank.filter(q => q.subject !== discipline);
        questions = questions.concat(extra);
      }
      if (questions.length < rounds) {
        const gen = generateLocalMedCopilotQuestions('Duelo PvP', discipline, rounds, {}, '');
        questions = questions.concat(gen);
      }

      const shuffled = questions.slice().sort(() => Math.random() - 0.5).slice(0, rounds);

      pvpBattleState = {
        active: true,
        subject: discipline,
        rounds: rounds,
        currentRound: 0,
        questions: shuffled,
        playerScore: 0,
        opponentScore: 0,
        timerInterval: null,
        timeLeft: 30,
        answeredCurrent: false,
        mode: mode
      };

      const setup = document.getElementById('pvpSetupScreen');
      const arena = document.getElementById('pvpArenaScreen');
      const result = document.getElementById('pvpResultScreen');
      if (setup) setup.style.display = 'none';
      if (arena) arena.style.display = 'flex';
      if (result) result.style.display = 'none';

      const oppName = document.getElementById('pvpOpponentName');
      if (oppName) oppName.textContent = mode === 'peer' ? 'Colega Desafiado' : 'Residente IA';

      loadPvpRound(0);
    }

    function loadPvpRound(roundIdx) {
      if (roundIdx >= pvpBattleState.questions.length) {
        finishPvpBattle();
        return;
      }

      if (pvpBattleState.timerInterval) clearInterval(pvpBattleState.timerInterval);

      pvpBattleState.currentRound = roundIdx;
      pvpBattleState.timeLeft = 30;
      pvpBattleState.answeredCurrent = false;

      const q = pvpBattleState.questions[roundIdx];

      const roundCounter = document.getElementById('pvpRoundCounter');
      if (roundCounter) roundCounter.textContent = `Rodada ${roundIdx + 1} de ${pvpBattleState.questions.length}`;

      const pScore = document.getElementById('pvpPlayerScore');
      if (pScore) pScore.textContent = `${pvpBattleState.playerScore} pts`;

      const oScore = document.getElementById('pvpOpponentScore');
      if (oScore) oScore.textContent = `${pvpBattleState.opponentScore} pts`;

      const feedback = document.getElementById('pvpRoundFeedback');
      if (feedback) feedback.style.display = 'none';

      const qText = document.getElementById('pvpQuestionText');
      if (qText) {
        qText.innerHTML = `
          <div style="font-size: 11px; font-weight: 700; color: var(--neon); text-transform: uppercase; margin-bottom: 6px;">
            Questão ${roundIdx + 1} • ${escapeHtml(q.disease || q.topic || pvpBattleState.subject)}
          </div>
          ${q.vignette ? `<div style="font-size: 12px; color: var(--text-secondary); margin-bottom: 8px; font-style: italic;">${escapeHtml(q.vignette)}</div>` : ''}
          ${escapeHtml(q.question)}
        `;
      }

      const optContainer = document.getElementById('pvpOptionsContainer');
      if (optContainer) {
        optContainer.innerHTML = (q.quizOptions || []).map((opt, idx) => `
          <button class="pvp-choice-btn" id="pvpOpt_${idx}" onclick="submitPvpAnswer(${idx})" style="text-align: left; padding: 10px 14px; font-size: 12.5px; border-radius: 10px; border: 1px solid var(--border); background: var(--bg-surface); color: var(--text-primary); cursor: pointer; display: flex; align-items: center; gap: 10px; transition: all 0.2s;">
            <span style="font-weight: 800; color: var(--neon); width: 22px; flex-shrink: 0;">${String.fromCharCode(65 + idx)})</span>
            <span style="flex: 1;">${escapeHtml(opt)}</span>
          </button>
        `).join('');
      }

      const timerEl = document.getElementById('pvpRoundTimer');
      if (timerEl) {
        timerEl.textContent = '⏱️ 30s';
        timerEl.style.color = '#00ff66';
        timerEl.style.borderColor = 'rgba(0, 255, 102, 0.4)';
      }

      pvpBattleState.timerInterval = setInterval(() => {
        pvpBattleState.timeLeft--;
        if (timerEl) {
          timerEl.textContent = `⏱️ ${pvpBattleState.timeLeft}s`;
          if (pvpBattleState.timeLeft <= 5) {
            timerEl.style.color = '#ff4444';
            timerEl.style.borderColor = 'rgba(255, 68, 68, 0.4)';
          } else if (pvpBattleState.timeLeft <= 15) {
            timerEl.style.color = '#ffaa00';
            timerEl.style.borderColor = 'rgba(255, 170, 0, 0.4)';
          }
        }
        if (pvpBattleState.timeLeft <= 0) {
          clearInterval(pvpBattleState.timerInterval);
          submitPvpAnswer(-1);
        }
      }, 1000);
    }

    function submitPvpAnswer(chosenIdx) {
      if (pvpBattleState.answeredCurrent) return;
      pvpBattleState.answeredCurrent = true;
      if (pvpBattleState.timerInterval) clearInterval(pvpBattleState.timerInterval);

      const q = pvpBattleState.questions[pvpBattleState.currentRound];
      if (!q) return;

      const isPlayerCorrect = chosenIdx === q.correctIndex;
      const speedBonus = isPlayerCorrect ? Math.floor(Math.max(0, pvpBattleState.timeLeft) * 2.5) : 0;
      const playerRoundPts = isPlayerCorrect ? (100 + speedBonus) : 0;
      pvpBattleState.playerScore += playerRoundPts;

      const aiCorrect = Math.random() < 0.75;
      const aiSpeedSec = Math.floor(8 + Math.random() * 14);
      const aiSpeedBonus = aiCorrect ? Math.floor(Math.max(2, 30 - aiSpeedSec) * 2.2) : 0;
      const aiRoundPts = aiCorrect ? (100 + aiSpeedBonus) : 0;
      pvpBattleState.opponentScore += aiRoundPts;

      if (typeof AppExpenseTracker !== 'undefined') {
        AppExpenseTracker.recordAction({
          actionName: `Duelo Clínico PvP: Rodada ${pvpBattleState.currentRound + 1} (${pvpBattleState.subject || 'Clínica'})`,
          isLocal: true
        });
      }

      (q.quizOptions || []).forEach((_, idx) => {
        const btn = document.getElementById(`pvpOpt_${idx}`);
        if (!btn) return;
        btn.disabled = true;
        btn.style.cursor = 'default';
        if (idx === q.correctIndex) {
          btn.style.background = 'rgba(0, 255, 102, 0.15)';
          btn.style.borderColor = '#00ff66';
          btn.style.color = '#00ff66';
        } else if (idx === chosenIdx && !isPlayerCorrect) {
          btn.style.background = 'rgba(255, 68, 68, 0.15)';
          btn.style.borderColor = '#ff4444';
          btn.style.color = '#ff4444';
        }
      });

      const pScore = document.getElementById('pvpPlayerScore');
      if (pScore) pScore.textContent = `${pvpBattleState.playerScore} pts`;
      const oScore = document.getElementById('pvpOpponentScore');
      if (oScore) oScore.textContent = `${pvpBattleState.opponentScore} pts`;

      const feedback = document.getElementById('pvpRoundFeedback');
      if (feedback) {
        feedback.style.display = 'block';
        if (isPlayerCorrect) {
          feedback.style.background = 'rgba(0, 255, 102, 0.12)';
          feedback.style.border = '1px solid rgba(0, 255, 102, 0.3)';
          feedback.style.color = '#00ff66';
          feedback.innerHTML = `<strong>🎉 Acertou!</strong> +${playerRoundPts} pts (Bônus de velocidade: +${speedBonus} pts).<br><span style="font-size: 11px; color: var(--text-secondary);">${pvpBattleState.mode === 'peer' ? 'Colega' : 'Residente IA'} ${aiCorrect ? `acertou em ${aiSpeedSec}s (+${aiRoundPts} pts)` : 'errou (+0 pts)'}.</span>`;
        } else {
          feedback.style.background = 'rgba(255, 68, 68, 0.12)';
          feedback.style.border = '1px solid rgba(255, 68, 68, 0.3)';
          feedback.style.color = '#ff6666';
          feedback.innerHTML = `<strong>❌ Incorreta ou Tempo Esgotado.</strong> Gabarito: alternativa ${String.fromCharCode(65 + q.correctIndex)} (+0 pts).<br><span style="font-size: 11px; color: var(--text-secondary);">${pvpBattleState.mode === 'peer' ? 'Colega' : 'Residente IA'} ${aiCorrect ? `acertou em ${aiSpeedSec}s (+${aiRoundPts} pts)` : 'errou (+0 pts)'}.</span>`;
        }
      }

      setTimeout(() => {
        loadPvpRound(pvpBattleState.currentRound + 1);
      }, 2500);
    }

    function finishPvpBattle() {
      if (pvpBattleState.timerInterval) clearInterval(pvpBattleState.timerInterval);
      pvpBattleState.active = false;

      const arena = document.getElementById('pvpArenaScreen');
      const result = document.getElementById('pvpResultScreen');
      if (arena) arena.style.display = 'none';
      if (result) result.style.display = 'flex';

      const pFinal = document.getElementById('pvpFinalPlayerScore');
      if (pFinal) pFinal.textContent = `${pvpBattleState.playerScore} pts`;

      const oFinal = document.getElementById('pvpFinalOpponentScore');
      if (oFinal) oFinal.textContent = `${pvpBattleState.opponentScore} pts`;

      const badge = document.getElementById('pvpResultBadge');
      const title = document.getElementById('pvpResultTitle');
      const desc = document.getElementById('pvpResultDesc');

      if (pvpBattleState.playerScore > pvpBattleState.opponentScore) {
        if (badge) badge.textContent = '🏆';
        if (title) { title.textContent = 'VITÓRIA CLÍNICA!'; title.style.color = 'var(--neon)'; }
        if (desc) desc.textContent = 'Você superou o oponente com agilidade e precisão de raciocínio clínico!';
      } else if (pvpBattleState.playerScore === pvpBattleState.opponentScore) {
        if (badge) badge.textContent = '⚔️';
        if (title) { title.textContent = 'EMPATE TÉCNICO!'; title.style.color = '#ffaa00'; }
        if (desc) desc.textContent = 'Disputa de alto nível! Domínio equivalente em todas as condutas.';
      } else {
        if (badge) badge.textContent = '🩺';
        if (title) { title.textContent = 'TREINO CONCLUÍDO!'; title.style.color = '#ff6666'; }
        if (desc) desc.textContent = 'O oponente foi mais rápido desta vez. Revise a matéria e tente um novo duelo!';
      }

      const xp = Math.max(25, Math.floor(pvpBattleState.playerScore / 2));
      gainStudentXp(xp);
    }

    function processSharedStudyMaterial() {
      promptMaterialDirection();
    }

    function handleMaterialFile(input) {
      if (input.files && input.files.length > 0) {
        if (input.files.length === 1) {
          const file = input.files[0];
          const sizeMB = file.size / (1024 * 1024);

          if (sizeMB > 300) {
            showToast(`⚠️ Arquivo de ${sizeMB.toFixed(0)} MB é excessivamente grande (> 300 MB). Divida por capítulos.`);
            input.value = '';
            return;
          }

          const zoneTitle = document.getElementById('materialUploadZoneTitle');
          const zoneSub = document.getElementById('materialUploadZoneSub');
          if (zoneTitle) zoneTitle.textContent = `📄 ${file.name} (${sizeMB >= 1 ? sizeMB.toFixed(1) + ' MB' : Math.round(sizeMB * 1024) + ' KB'})`;
          if (zoneSub) {
            zoneSub.textContent = '✓ Arquivo selecionado • Conteúdo será analisado com PDF.js e IA';
            zoneSub.style.color = 'var(--neon)';
          }

          if (sizeMB >= 100) {
            showToast(`⚡ Compactador Local Ativo: ${sizeMB.toFixed(0)} MB será reduzido no seu aparelho em ~70% (sem IA).`);
          } else {
            showToast(`📄 Arquivo "${file.name}" carregado. Clique em "Processar Materiais" para analisar.`);
          }
        } else {
          const zoneTitle = document.getElementById('materialUploadZoneTitle');
          const zoneSub = document.getElementById('materialUploadZoneSub');
          if (zoneTitle) zoneTitle.textContent = `📁 ${input.files.length} arquivos selecionados`;
          if (zoneSub) {
            zoneSub.textContent = Array.from(input.files).map(f => f.name).slice(0, 3).join(', ') + (input.files.length > 3 ? '...' : '');
            zoneSub.style.color = 'var(--neon)';
          }
          showToast(`📁 ${input.files.length} arquivos prontos para alocação item a item.`);
        }
      }
    }

