    function updateGeminiKeyBadge() {
      const badge = document.getElementById('geminiKeySavedBadge');
      const input = document.getElementById('geminiApiKeyInput');
      const key = getGeminiApiKey();
      if (badge) badge.style.display = key ? 'inline-block' : 'none';
      if (input && key && !input.value) input.value = key;
    }

    // REPARADOR RESILIENTE DE RESPOSTAS JSON TRUNCADAS DE IA (TOLERÂNCIA A LIMITES DE TOKENS)
    function repairTruncatedJsonArray(jsonStr) {
      if (!jsonStr || typeof jsonStr !== 'string') return null;
      let clean = jsonStr.trim();
      const firstBracket = clean.indexOf('[');
      if (firstBracket !== -1) {
        clean = clean.slice(firstBracket);
      }
      try {
        const parsed = JSON.parse(clean);
        if (Array.isArray(parsed)) return parsed;
      } catch (e) {
        // Se foi truncado pelo limite de saída de tokens, encontra o último fechamento de objeto '}'
        const lastCloseBrace = clean.lastIndexOf('}');
        if (lastCloseBrace !== -1) {
          const repaired = clean.slice(0, lastCloseBrace + 1) + ']';
          try {
            const parsed = JSON.parse(repaired);
            if (Array.isArray(parsed) && parsed.length > 0) {
              console.warn(`JSON truncado recuperado com sucesso: ${parsed.length} disciplinas resgatadas.`);
              return parsed;
            }
          } catch (e2) {}
        }
      }
      return null;
    }

    // =========================================================================
    // INTEGRAÇÃO COM IA GEMINI: ARQUITETURA EM LOTES POR CICLO MÉDICO DAS DCNS
    // Zero truncamento de tokens (gemini-3.5-flash e gemini-3.5-flash-lite)
    // =========================================================================

    async function callGeminiCycleAnalysis(cycleConfig, rawText, apiKey) {
       if (!rawText || !apiKey) return [];
       const models = GEMINI_CONFIG_2026.models;
       const promptText = `Você é um extrator de dados cirúrgico e estrito. Sua ÚNICA função é listar as disciplinas EXPLICITAMENTE ESCRITAS no texto abaixo que pertençam ao ciclo indicado.

🚨 REGRAS ABSOLUTAS ANTI-ALUCINAÇÃO:
1. PROIBIDO inventar, sugerir ou completar disciplinas com conhecimento externo. Se uma disciplina não estiver escrita no texto, ela NÃO existe.
2. PROIBIDO inferir disciplinas a partir de padrões de currículos nacionais. Baseie-se EXCLUSIVAMENTE no texto fornecido.
3. Se o texto não contiver disciplinas do ciclo solicitado, retorne array vazio [].
4. Os campos "description" e "topics" devem ser extraídos do próprio texto. Se não houver descrição no texto, use string vazia "". Se não houver tópicos, use array vazio [].

🎯 CICLO ALVO: ${cycleConfig.targetTitle} (${cycleConfig.targetPeriods})
${cycleConfig.specificInstructions}

FORMATO DE SAÍDA por disciplina encontrada no texto:
- "name": Nome EXATO como aparece no texto (preservar código se houver, ex: "${cycleConfig.exampleName}")
- "period": Período EXATO como aparece no texto (ex: "${cycleConfig.examplePeriod}")
- "cycle": "${cycleConfig.cycleKey}"
- "cycleName": "${cycleConfig.cycleName}"
- "description": Texto da ementa extraído do documento (pode ser vazio se não constar)
- "topics": Tópicos/conteúdos listados no documento para essa disciplina (pode ser array vazio)

TEXTO DO DOCUMENTO (extraia SOMENTE daqui):
${rawText}`;

       const payload = {
         contents: [{ parts: [{ text: promptText }] }],
         generationConfig: {
           temperature: 0,
           maxOutputTokens: 8192,
           responseMimeType: "application/json",
           responseSchema: {
             type: "ARRAY",
             items: {
               type: "OBJECT",
               properties: {
                 name: { type: "STRING" },
                 period: { type: "STRING" },
                 cycle: { type: "STRING", enum: ["basico", "clinico", "internato"] },
                 cycleName: { type: "STRING" },
                 description: { type: "STRING" },
                 topics: { type: "ARRAY", items: { type: "STRING" } }
               },
               required: ["name", "cycle", "cycleName", "description", "topics"]
             }
           }
         }
       };

      for (const model of models) {
        try {
          const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey.trim())}`;
          const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          if (!res.ok) {
            let errBody = '';
            try { errBody = await res.text(); } catch (_) {}
            console.warn(`Gemini API (${cycleConfig.targetTitle}) modelo ${model} HTTP ${res.status}:`, errBody);
            continue;
          }

          const data = await res.json();

          // Gemini 2.5 Flash com thinking pode ter múltiplas parts; pega a última (JSON)
          const parts = data.candidates?.[0]?.content?.parts || [];
          const contentStr = parts.map(p => p.text || '').filter(t => t.trim()).pop() || '';
          if (!contentStr) {
            console.warn(`Gemini (${model}) retornou resposta vazia ou sem text part.`, data);
            continue;
          }

          const parsedJson = repairTruncatedJsonArray(contentStr);
          if (Array.isArray(parsedJson) && parsedJson.length > 0) {
            if (typeof AppExpenseTracker !== 'undefined') {
              const inTok = data.usageMetadata?.promptTokenCount || Math.ceil(promptText.length / 4);
              const outTok = data.usageMetadata?.candidatesTokenCount || Math.ceil(contentStr.length / 4);
              AppExpenseTracker.recordAction({
                actionName: `Análise de Ementa - ${cycleConfig.targetTitle} (${parsedJson.length} disciplinas)`,
                model: model,
                inputTokens: inTok,
                outputTokens: outTok,
                isLocal: false
              });
            }
            return parsedJson.map((item, idx) => {
              return buildSubjectObject(item.name, item.period || cycleConfig.examplePeriod, item.description, item.topics, idx);
            }).filter(Boolean);
          }
          console.warn(`Gemini (${model}) retornou JSON inválido ou vazio:`, contentStr.slice(0, 200));
        } catch (err) {
          console.warn(`Erro no modelo ${model} para ${cycleConfig.targetTitle}:`, err);
        }
      }
      return [];
    }

    async function analyzeSyllabusWithGeminiInBatches(rawText, apiKey) {
      if (!rawText || !apiKey) return null;

      // Se o texto for curto (< 3500 caracteres ou ementa isolada), análise rápida em chamada única
      if (rawText.length < 3500) {
        return await analyzeSyllabusWithGemini(rawText, apiKey);
      }

      // Para PPCs completos, matrizes e ementários universitários (50 a 85 disciplinas):
      // Arquitetura de 3 Lotes Concorrentes por Ciclo Médico das DCNs para eliminação total de truncamento de tokens
      const cycleConfigs = [
        {
          targetTitle: 'Ciclo Básico',
          targetPeriods: '1º, 2º, 3º e 4º Períodos / Semestres ou 1º e 2º Anos',
          cycleKey: 'basico',
          cycleName: 'Ciclo Básico',
          exampleName: 'M001 Anatomia Humana I',
          examplePeriod: '1º Período • Ciclo Básico',
          specificInstructions: 'Extraia EXCLUSIVAMENTE disciplinas do Ciclo Básico (ex: Anatomia, Fisiologia, Bioquímica, Histologia, Embriologia, Imunologia, Genética, Microbiologia, Parasitologia, Patologia Geral, Farmacologia Básica, Semiologia Inicial, Saúde Coletiva I-IV). NÃO inclua disciplinas do Ciclo Clínico nem do Internato.'
        },
        {
          targetTitle: 'Ciclo Clínico',
          targetPeriods: '5º, 6º, 7º e 8º Períodos / Semestres ou 3º e 4º Anos',
          cycleKey: 'clinico',
          cycleName: 'Ciclo Clínico',
          exampleName: 'M025 Cardiologia e Doenças Cardiovasculares',
          examplePeriod: '5º Período • Ciclo Clínico',
          specificInstructions: 'Extraia EXCLUSIVAMENTE disciplinas do Ciclo Clínico (ex: Cardiologia, Pneumologia, Nefrologia, Gastroenterologia, Infectologia, Reumatologia, Hematologia, Endocrinologia, Dermatologia, Neurologia, Cirurgia Geral, Anestesiologia, Ortopedia, Oftalmologia, Otorrinolaringologia, Ginecologia, Obstetrícia, Pediatria, Psiquiatria, Medicina Legal). NÃO inclua Ciclo Básico nem Internato.'
        },
        {
          targetTitle: 'Internato Médico e Optativas',
          targetPeriods: '9º, 10º, 11º e 12º Períodos / Semestres ou 5º e 6º Anos / Estágios Supervisionados / Optativas',
          cycleKey: 'internato',
          cycleName: 'Internato Médico',
          exampleName: 'INT01 Internato em Clínica Médica I',
          examplePeriod: '9º Período • Internato Médico',
          specificInstructions: 'Extraia EXCLUSIVAMENTE disciplinas e estágios do Internato Médico (ex: Internato em Clínica Médica, Internato em Cirurgia Geral, Internato em Pediatria, Internato em Saúde Coletiva / Medicina de Família e Comunidade, Internato em Ginecologia e Obstetrícia, Urgência e Emergência, Estágios Optativos e Eletivos). NÃO inclua disciplinas do Ciclo Básico nem do Clínico.'
        }
      ];

      try {
        // Disparo concorrente em 3 lotes paralelos (máxima velocidade e zero truncamento)
        const results = await Promise.all(cycleConfigs.map(cfg => callGeminiCycleAnalysis(cfg, rawText, apiKey)));
        const combined = [];
        const seen = new Set();

        results.forEach(cycleBatch => {
          if (Array.isArray(cycleBatch)) {
            cycleBatch.forEach(subj => {
              if (!subj || !subj.name) return;
              const cleanN = cleanSubjectName(subj.name).toLowerCase();
              const codeMatch = subj.name.match(/\b([A-Z]{2,6}[\-\s]?\d{2,5}|M\d{3})\b/i);
              const dedupeKey = codeMatch ? codeMatch[1].toUpperCase() : cleanN;
              if (!seen.has(dedupeKey)) {
                seen.add(dedupeKey);
                combined.push(subj);
              }
            });
          }
        });

        if (combined.length > 0) {
          console.log(`[MedTutor Ingestão IA] Sucesso em 3 lotes: ${combined.length} disciplinas resgatadas.`);
          return combined;
        }
      } catch (batchErr) {
        console.warn('Erro na execução em lotes do Gemini:', batchErr);
      }

      // Fallback para chamada única se a chamada em lote falhar
      return await analyzeSyllabusWithGemini(rawText, apiKey);
    }

    // INTEGRAÇÃO COM IA GEMINI (MENOR CUSTO & RESPOSTA ESTRUTURADA EM JSON)
    async function analyzeSyllabusWithGemini(rawText, apiKey) {
      if (!rawText || !apiKey) return null;
      // Modelos de máxima economia (gemini-3.5-flash-lite prioritário, gemini-3.5-flash fallback, zero pro/ultra)
      const models = GEMINI_CONFIG_2026.models;

      const promptText = `Você é um extrator de dados cirúrgico e estrito. Sua ÚNICA função é listar as disciplinas EXPLICITAMENTE ESCRITAS no texto abaixo.

🚨 REGRAS ABSOLUTAS ANTI-ALUCINAÇÃO:
1. PROIBIDO inventar, sugerir ou completar disciplinas com conhecimento externo. Se uma disciplina não estiver escrita no texto, ela NÃO existe.
2. PROIBIDO inferir disciplinas a partir de padrões de currículos nacionais ou DCNs do MEC. Baseie-se EXCLUSIVAMENTE no texto fornecido.
3. Não tente "completar" períodos ausentes. Se o texto só tem 3 períodos, extraia apenas esses 3.
4. Os campos "description" e "topics" devem ser extraídos do próprio texto. Se não houver descrição no texto, use string vazia "". Se não houver tópicos, use array vazio [].

FORMATO DE SAÍDA por disciplina encontrada no texto:
- "name": Nome EXATO como aparece no texto (preservar código se houver)
- "period": Período EXATO como aparece no texto
- "cycle": "basico", "clinico" ou "internato" (inferir pelo número do período)
- "cycleName": "Ciclo Básico", "Ciclo Clínico" ou "Internato Médico"
- "description": Texto da ementa extraído do documento (string vazia se não constar)
- "topics": Tópicos/conteúdos listados no documento para essa disciplina (array vazio se não constar)

TEXTO DO DOCUMENTO (extraia SOMENTE daqui):
${rawText}`;

      const payload = {
        contents: [{ parts: [{ text: promptText }] }],
        generationConfig: {
          temperature: 0,
          maxOutputTokens: 8192,
          responseMimeType: "application/json",
          responseSchema: {
            type: "ARRAY",
            items: {
              type: "OBJECT",
              properties: {
                name: { type: "STRING" },
                period: { type: "STRING" },
                cycle: { type: "STRING", enum: ["basico", "clinico", "internato"] },
                cycleName: { type: "STRING" },
                description: { type: "STRING" },
                topics: { type: "ARRAY", items: { type: "STRING" } }
              },
              required: ["name", "cycle", "cycleName", "description", "topics"]
            }
          }
        }
      };

      for (const model of models) {
        try {
          const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey.trim())}`;
          const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });

          if (!res.ok) {
            let errBody = '';
            try { errBody = await res.text(); } catch (_) {}
            console.warn(`Gemini API modelo ${model} HTTP ${res.status}:`, errBody);
            continue;
          }

          const data = await res.json();

          // Gemini 2.5 Flash com thinking pode retornar múltiplas parts; pega a última (JSON)
          const parts = data.candidates?.[0]?.content?.parts || [];
          const contentStr = parts.map(p => p.text || '').filter(t => t.trim()).pop() || '';
          if (!contentStr) {
            console.warn(`Gemini (${model}) retornou resposta vazia:`, data);
            continue;
          }

          const parsedJson = repairTruncatedJsonArray(contentStr);
          if (Array.isArray(parsedJson) && parsedJson.length > 0) {
            if (typeof AppExpenseTracker !== 'undefined') {
              const inTok = data.usageMetadata?.promptTokenCount || Math.ceil(promptText.length / 4);
              const outTok = data.usageMetadata?.candidatesTokenCount || Math.ceil(contentStr.length / 4);
              AppExpenseTracker.recordAction({
                actionName: `Análise Integral de Ementa (${parsedJson.length} disciplinas)`,
                model: model,
                inputTokens: inTok,
                outputTokens: outTok,
                isLocal: false
              });
            }
            return parsedJson.map((item, idx) => {
              return buildSubjectObject(item.name, item.period, item.description, item.topics, idx);
            }).filter(Boolean);
          }
          console.warn(`Gemini (${model}) JSON inválido:`, contentStr.slice(0, 200));
        } catch (err) {
          console.warn(`Erro no modelo ${model}:`, err);
        }
      }
      return null;
    }

    // NORMALIZAÇÃO DE TEXTO DA EMENTA (REMOÇÃO DE CABEÇALHOS PDF E DESAGREGAÇÃO ESTRUTURAL DE LINHAS)
    function normalizeSyllabusText(text) {
      if (!text || typeof text !== 'string') return '';
      let clean = text
        .replace(/[\x00-\x08\x0B\x0C\x0E-\x1F\x7F]/g, '')
        .replace(/\r\n/g, '\n')
        .replace(/\r/g, '\n');

      // Remove resíduos de prompts ou tags de metadados inseridos acidentalmente
      clean = clean.replace(/<\/?(?:USER_REQUEST|ADDITIONAL_METADATA)>[\s\S]*?(?:$|\n)/gi, '\n');
      clean = clean.replace(/\best[aá]\s+gerando\s+um\s+[uú]nico\s+card[^\n\r]*/gi, '');

      // Remove cabeçalhos e rodapés repetitivos de páginas de PDF
      clean = clean.replace(/\b\d+\s*[-–—]\s*\d+\s+Universidade\s+[^\n\r]*?EMENTÁ\s*RIO/gi, '\n\n');
      clean = clean.replace(/\b\d+\s*[-–—]\s*\d+\s+[A-Za-zÀ-ÿ\s\-–—]+?(?:ESTRUTURA\s+CURRICULAR|EMENT[AÁ]RIO|PROJETO\s+PEDAG[OÓ]GICO)[^\n\r]*/gi, '\n\n');
      clean = clean.replace(/\b\d+\s*[-–—]\s*\d+\s+Universidade\b[^\n\r]*/gi, '\n\n');
      clean = clean.replace(/\bP[aá]gina\s+\d+\s+de\s+\d+\b/gi, '\n\n');

      // Quebra linhas contínuas de PDFs onde seções estruturais ficaram aglutinadas
      const markers = [
        '(?:[0-9]+º|[0-9]+o|[0-9]+ª|[0-9]+\\b)\\s+(?:Semestre|Per[ií]odo|Fase|Termo|Ano|Série|Etapa)(?:\\s*\\([A-Za-z\\s]+\\))?',
        '(?:PRIMEIRO|SEGUNDO|TERCEIRO|QUARTO|QUINTO|SEXTO|S[EÉ]TIMO|OITAVO|NONO|D[EÉ]CIMO(?:\\s+PRIMEIRO|\\s+SEGUNDO)?)\\s+(?:PER[IÍ]ODO|SEMESTRE)',
        '(?:PER[IÍ]ODO|SEMESTRE|FASE|TERMO)\\s+(?:[0-9]+|XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\\b',
        '(?:CICLO\\s+DE\\s+|CICLO\\s+DO\\s+)?INTERNATO\\s+M[EÉ]DICO\\s*[:\\-–]',
        'Disciplina\\s*:',
        'Componente\\s+Curricular\\s*:',
        'Unidade\\s+Curricular\\s*:',
        'M[oó]dulo\\s+(?:Curricular)?\\s*:',
        'Atividade\\s+(?:Did[aá]tica|Curricular)\\s*:',
        'Carga\\s+Hor[aá]ria\\s*[:/]',
        'Ementa\\s*[:\\-–]',
        'S[uú]mula\\s*[:\\-–]',
        'Conte[uú]do\\s+Program[aá]tico\\s*[:\\-–]',
        'Bibliografia\\s+B[aá]sica\\s*:',
        'Bibliografia\\s+Complementar\\s*:',
        'Objetivos\\s*:',
        'Compet[eê]ncias\\s*:'
      ];

      for (const m of markers) {
        const regex = new RegExp('([\\s;•]+)(' + m + ')', 'gi');
        clean = clean.replace(regex, '\n$2\n');
      }

      return clean;
    }

    // RESOLUÇÃO PRECISA DE PERÍODOS E CICLOS MÉDICOS CONFORME AS DCNS
    function resolvePeriodAndCycle(periodRaw, name, description) {
      let p = (periodRaw || '').trim();

      // Constantes de mapeamento
      const romanMap = {
        'XII': 12, 'XI': 11, 'X': 10, 'IX': 9, 'VIII': 8,
        'VII': 7, 'VI': 6, 'V': 5, 'IV': 4, 'III': 3, 'II': 2, 'I': 1
      };
      const romanRegex1 = /\b(?:semestre|per[ií]odo|fase|termo|etapa)\s*(XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\b/i;
      const romanRegex2 = /\b(XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\s*(?:semestre|per[ií]odo|fase|termo|etapa)\b/i;

      const writtenMap = [
        { pattern: /\b(?:d[eé]cimo[\s\-]segundo|decimo[\s\-]segundo)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 12 },
        { pattern: /\b(?:d[eé]cimo[\s\-]primeiro|decimo[\s\-]primeiro)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 11 },
        { pattern: /\b(?:d[eé]cimo|decimo)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 10 },
        { pattern: /\b(?:nono)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 9 },
        { pattern: /\b(?:oitavo)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 8 },
        { pattern: /\b(?:s[eé]timo|setimo)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 7 },
        { pattern: /\b(?:sexto)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 6 },
        { pattern: /\b(?:quinto)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 5 },
        { pattern: /\b(?:quarto)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 4 },
        { pattern: /\b(?:terceiro)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 3 },
        { pattern: /\b(?:segundo)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 2 },
        { pattern: /\b(?:primeiro)\s*(?:semestre|per[ií]odo|fase|termo|ano|etapa)?\b/i, num: 1 }
      ];

      // FASE 1: Se o cabeçalho de período (periodRaw) já foi identificado na matriz, ele é autoritativo
      if (p && !/^disciplinas\b/i.test(p)) {
        // 1.1 Regime Anual em p (1º ao 6º Ano Médico)
        const yrMatch = p.match(/\b([1-6])º?\s*(?:ano|série|serie)\b/i);
        if (yrMatch) {
          const yr = parseInt(yrMatch[1], 10);
          const mappedPeriod = ((yr - 1) * 2) + 1;
          const finalPeriod = `${mappedPeriod}º Período (${yr}º Ano)`;
          if (yr <= 2) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
          if (yr <= 4) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
          return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
        }

        // 1.2 Arábico explícito em p (1 a 12)
        const pNumMatch = p.match(/\b(1[0-2]|[1-9])[ºªo\.]?\s*(?:semestre|per[ií]odo|termo|etapa|fase)/i) ||
                           p.match(/^(?:semestre|per[ií]odo|termo|etapa|fase)\s*(1[0-2]|[1-9])\b/i) ||
                           p.match(/\b(1[0-2]|[1-9])\b/);
        if (pNumMatch) {
          const num = parseInt(pNumMatch[1], 10);
          let finalPeriod = p;
          if (!p || /^\d+$/.test(p)) {
            finalPeriod = `${num}º Período`;
          } else if (/^\d+[\.ºªo\s]+per[ií]odo$/i.test(p)) {
            finalPeriod = `${num}º Período`;
          } else if (/^\d+[\.ºªo\s]+semestre$/i.test(p)) {
            finalPeriod = `${num}º Semestre`;
          }
          if (num <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
          if (num <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
          return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
        }

        // 1.3 Numerais Romanos em p
        const rMatch = p.match(romanRegex1) || p.match(romanRegex2);
        if (rMatch) {
          const rVal = romanMap[rMatch[1].toUpperCase()];
          if (rVal) {
            const finalPeriod = `${rVal}º Período`;
            if (rVal <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
            if (rVal <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
            return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
          }
        }

        // 1.4 Extenso em p
        for (const w of writtenMap) {
          if (w.pattern.test(p)) {
            const finalPeriod = `${w.num}º Período`;
            if (w.num <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
            if (w.num <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
            return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
          }
        }

        // 1.5 Internato explícito em p
        if (/internato|est[aá]gio\s+supervisionado|est[aá]gio\s+curricular/i.test(p)) {
          if (/internato\s*(?:2|ii|2º|segundo)|6º\s*ano/i.test(p)) {
            return { period: '11º Período • Internato Médico II', cycle: 'internato', cycleName: 'Internato Médico' };
          }
          return { period: p || '9º Período • Internato Médico', cycle: 'internato', cycleName: 'Internato Médico' };
        }

        // 1.6 Optativas em p
        if (/optativ|eletiv/i.test(p)) {
          return { period: p || 'Disciplinas Optativas', cycle: 'clinico', cycleName: 'Disciplinas Optativas' };
        }
      }

      // FASE 2: Período não constava no cabeçalho ou era genérico; infere do nome da disciplina e descrição
      const combined = (p + ' ' + (name || '') + ' ' + (description || '')).toLowerCase();

      // 2.1 Ordinais por extenso em combined
      for (const w of writtenMap) {
        if (w.pattern.test(combined)) {
          const finalPeriod = `${w.num}º Período`;
          if (w.num <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
          if (w.num <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
          return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
        }
      }

      // 2.2 Romanos em combined (somente acompanhados de semestre/período/fase/termo)
      const rMatchComb = combined.match(romanRegex1) || combined.match(romanRegex2);
      if (rMatchComb) {
        const rVal = romanMap[rMatchComb[1].toUpperCase()];
        if (rVal) {
          const finalPeriod = `${rVal}º Período`;
          if (rVal <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
          if (rVal <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
          return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
        }
      }

      // 2.3 Anos em combined
      const yrMatchComb = combined.match(/\b([1-6])º?\s*(?:ano|série|serie)\b/i);
      if (yrMatchComb) {
        const yr = parseInt(yrMatchComb[1], 10);
        const mappedPeriod = ((yr - 1) * 2) + 1;
        const finalPeriod = `${mappedPeriod}º Período (${yr}º Ano)`;
        if (yr <= 2) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
        if (yr <= 4) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
        return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
      }

      // 2.4 Arábico em combined
      const pNumMatchComb = combined.match(/\b(1[0-2]|[1-9])[ºªo\.]?\s*(?:semestre|per[ií]odo|termo|etapa|fase)/i);
      if (pNumMatchComb) {
        const num = parseInt(pNumMatchComb[1], 10);
        const finalPeriod = `${num}º Período`;
        if (num <= 4) return { period: finalPeriod, cycle: 'basico', cycleName: 'Ciclo Básico' };
        if (num <= 8) return { period: finalPeriod, cycle: 'clinico', cycleName: 'Ciclo Clínico' };
        return { period: finalPeriod, cycle: 'internato', cycleName: 'Internato Médico' };
      }

      // 2.5 Internato em combined
      if (/internato|est[aá]gio\s+supervisionado|est[aá]gio\s+curricular/i.test(combined)) {
        if (/internato\s*(?:2|ii|2º|segundo)|6º\s*ano/i.test(combined)) {
          return { period: '11º Período • Internato Médico II', cycle: 'internato', cycleName: 'Internato Médico' };
        }
        return { period: p || '9º Período • Internato Médico', cycle: 'internato', cycleName: 'Internato Médico' };
      }

      // 2.6 Optativas em combined
      if (/optativ|eletiv/i.test(combined)) {
        return { period: p || 'Disciplinas Optativas', cycle: 'clinico', cycleName: 'Disciplinas Optativas' };
      }

      // 2.7 Fallback semântico por temas médicos
      if (/\b(?:1º|1o|primeiro)\b|anatomia|histologia|bioqu[ií]mica|citologia/i.test(combined)) {
        return { period: p || '1º Período • Ciclo Básico', cycle: 'basico', cycleName: 'Ciclo Básico' };
      }
      if (/\b(?:2º|2o|segundo)\b|fisiologia|gen[eé]tica|imunologia/i.test(combined)) {
        return { period: p || '2º Período • Ciclo Básico', cycle: 'basico', cycleName: 'Ciclo Básico' };
      }
      if (/\b(?:3º|3o|terceiro)\b|microbiologia|parasitologia|patologia\s+geral/i.test(combined)) {
        return { period: p || '3º Período • Ciclo Básico', cycle: 'basico', cycleName: 'Ciclo Básico' };
      }
      if (/\b(?:4º|4o|quarto)\b|semiologia|farmacologia|patologia\s+especial/i.test(combined)) {
        return { period: p || '4º Período • Ciclo Básico', cycle: 'basico', cycleName: 'Ciclo Básico' };
      }
      if (/\b(?:5º|5o|quinto)\b|cardiologia|pneumologia|nefrologia|gastro/i.test(combined)) {
        return { period: p || '5º Período • Ciclo Clínico', cycle: 'clinico', cycleName: 'Ciclo Clínico' };
      }
      if (/\b(?:6º|6o|sexto)\b|dermatologia|endocrinologia|hematologia|reumatologia|infectologia/i.test(combined)) {
        return { period: p || '6º Período • Ciclo Clínico', cycle: 'clinico', cycleName: 'Ciclo Clínico' };
      }
      if (/\b(?:7º|7o|s[eé]timo)\b|cirurgia|ortopedia|oftalmologia|otorrino|neurologia/i.test(combined)) {
        return { period: p || '7º Período • Ciclo Clínico', cycle: 'clinico', cycleName: 'Ciclo Clínico' };
      }
      if (/\b(?:8º|8o|oitavo)\b|ginecologia|obstetr[ií]cia|pediatria|psiquiatria|urg[eê]ncia/i.test(combined)) {
        return { period: p || '8º Período • Ciclo Clínico', cycle: 'clinico', cycleName: 'Ciclo Clínico' };
      }
      if (/\b(?:9º|10º|11º|12º|nono|d[eé]cimo)\b|internato/i.test(combined)) {
        return { period: p || 'Internato Médico', cycle: 'internato', cycleName: 'Internato Médico' };
      }

      return { period: p || 'Disciplinas da Ementa', cycle: 'clinico', cycleName: 'Ciclo Universitário' };
    }

    function buildSubjectObject(name, periodRaw, description, topics, index) {
      if (!isValidSubjectName(name) || isGarbageOrBinaryText(name)) return null;

      let cleanDesc = (typeof description === 'string' && !isGarbageOrBinaryText(description)) ? description.trim() : '';
      const cleanTopics = Array.isArray(topics)
        ? topics.filter(t => typeof t === 'string' && t.trim().length >= 2 && !isGarbageOrBinaryText(t)).map(t => t.trim())
        : [];

      const periodCycle = resolvePeriodAndCycle(periodRaw, name, cleanDesc);
      const textKeywords = extractKeywords(`${name} ${cleanDesc} ${cleanTopics.join(' ')}`);

      return {
        name: name,
        period: periodCycle.period,
        cycle: periodCycle.cycle,
        cycleName: periodCycle.cycleName,
        description: cleanDesc,
        topics: cleanTopics,
        keywords: textKeywords,
        isUser: true
      };
    }

    // PARSER UNIVERSAL DE EMENTA UNIVERSITÁRIA E PROJETO PEDAGÓGICO DE CURSO (PPC) - MOTOR HEURÍSTICO V2
    function parseEmentaWithDescriptions(text) {
      if (!text || typeof text !== 'string') return [];
      if (isGarbageOrBinaryText(text)) return [];

      const clean = normalizeSyllabusText(text);
      const lines = clean.split('\n').map(l => l.trim()).filter(Boolean);
      if (lines.length === 0) return [];

      const subjectMap = new Map();

      function addOrUpdateSubject(candidate) {
        if (!candidate || !candidate.name) return;
        const cleanName = cleanSubjectName(candidate.name);
        if (!isValidSubjectName(cleanName)) return;

        const codeMatch = candidate.name.match(/\b([A-Z]{2,6}[\-\s]?\d{2,5}|M\d{3}|OPT(?:\s+[A-Za-z0-9]+)?|AC)\b/i);
        const code = candidate.code || (codeMatch ? codeMatch[1].toUpperCase() : '');
        const key = code || cleanName.toLowerCase();

        let topics = Array.isArray(candidate.topics) ? [...candidate.topics] : [];
        if (candidate.description && topics.length === 0) {
          const parts = candidate.description
            .split(/(?:\.\s+|;\s+|\n+)/)
            .map(p => p.trim().replace(/^[\*\•\-\s0-9\.\)]+/, ''))
            .filter(p => p.length >= 4 && !isGarbageOrBinaryText(p) && !/^(?:bibliografia|refer[eê]ncias|carga hor[aá]ria|cr[eé]ditos)/i.test(p));
          topics = parts.slice(0, 35);
        }

        if (subjectMap.has(key)) {
          const existing = subjectMap.get(key);
          if (!existing.description && candidate.description) {
            existing.description = candidate.description;
          }
          if (existing.topics.length === 0 && topics.length > 0) {
            existing.topics = topics;
          }
          if ((!existing.period || existing.period.includes('Disciplinas')) && candidate.period) {
            existing.period = candidate.period;
          }
        } else {
          // Suporta até 300 disciplinas por ementário universitário completo (sem cortes prematuros)
          if (subjectMap.size >= 300) return;
          const obj = buildSubjectObject(candidate.name, candidate.period, candidate.description, topics, subjectMap.size);
          if (obj) {
            subjectMap.set(key, obj);
          }
        }
      }

      // SUB-PARSER 1: Matriz Curricular (1º ao 12º Semestre/Internato, Anos Médicos e Optativas)
      let currentPeriod = '';
      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];
        const pMatch = line.match(/^((?:[0-9]+º|[0-9]+o|[0-9]+ª|[0-9]+\b)\s+(?:Semestre|Per[ií]odo|Fase|Termo|Ano|Série|Etapa)(?:\s*\([A-Za-z\s]+\))?|(?:Semestre|Per[ií]odo|Fase|Termo)\s+(?:[0-9]+|XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)|(?:PRIMEIRO|SEGUNDO|TERCEIRO|QUARTO|QUINTO|SEXTO|S[EÉ]TIMO|OITAVO|NONO|D[EÉ]CIMO(?:\s+PRIMEIRO|\s+SEGUNDO)?)\s+PER[IÍ]ODO|Optativas?\s*(?:I|II|III|IV|V|VI|[0-9]+)?|(?:M[oó]dulo\s+do\s+|Ciclo\s+do\s+)?Internato(?:\s+M[eé]dico)?\s*$)/i);
        if (pMatch && !/^(?:OPT\s+)?Optativa\s+[I|V|X\d]+\s+\d+\s+\d+/i.test(line) && !/\b(?:\d+\s+\d+|\d+\s*h|\d+\s*horas?)\s*$/i.test(line.trim())) {
          currentPeriod = pMatch[1].trim();
        }

        if (/(?:CÓD\.\s*UNIDADE|CH\s*Te[oó]rica|Total Hora Aula|Matriz|Grade)/i.test(line) || currentPeriod) {
          // Linhas com código de disciplina e carga horária
          const rowRegex = /\b([A-Z]{2,6}[\-\s]?\d{2,5}|M\d{3}|OPT(?:\s+[A-Za-z0-9]+)?|AC)\s+([A-Za-zÀ-ÿ][A-Za-zÀ-ÿ0-9\s\(\)\:\,\-\–\.\/]+?)(?:\s+(\d+)\s+(\d+)|\s+(\d+)\s*h|\s+(\d+)\s*cr[eé]ditos?|$)/gi;
          let m;
          let matchedAny = false;
          while ((m = rowRegex.exec(line)) !== null) {
            matchedAny = true;
            const code = m[1].trim();
            let name = m[2].trim().replace(/\s+(?:Total|CH|Hora|Aula|hora\s*-\s*relógio)$/i, '');
            if (!name.toUpperCase().includes('UNIDADE CURRICULAR') && !name.toUpperCase().includes('TOTAL')) {
              addOrUpdateSubject({
                code: code,
                name: `${code} ${name}`,
                period: currentPeriod || '1º Semestre',
                description: '',
                topics: []
              });
            }
          }

          // Linhas tabulares ou com múltiplos espaços dentro de um período reconhecido
          if (!matchedAny && currentPeriod && line.length > 5 && line.length < 180) {
            const tabCols = line.split(/\t+|\s{3,}/).map(c => c.trim()).filter(Boolean);
            if (tabCols.length >= 2) {
              const codeCand = tabCols[0].match(/^[A-Z0-9]{2,8}$/i) ? tabCols[0] : '';
              const nameCand = codeCand ? tabCols[1] : tabCols[0];
              if (isValidSubjectName(nameCand) && !/^(?:total|semestre|per[ií]odo|disciplina|carga)/i.test(nameCand)) {
                addOrUpdateSubject({
                  code: codeCand,
                  name: codeCand ? `${codeCand} ${nameCand}` : nameCand,
                  period: currentPeriod,
                  description: '',
                  topics: []
                });
              }
            }
          }
        }
      }

      // SUB-PARSER 2: Ementário Detalhado por Disciplina (PPCs e Manuais de Curso)
      let currentBlock = null;
      let blockSection = '';
      let blockPeriod = '';

      for (let i = 0; i < lines.length; i++) {
        const line = lines[i];

        const pMatch = line.match(/^((?:(?:[0-9]+[\.ºªo\s]+|XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I\s+|(?:PRIMEIRO|SEGUNDO|TERCEIRO|QUARTO|QUINTO|SEXTO|S[EÉ]TIMO|OITAVO|NONO|D[EÉ]CIMO(?:\s+PRIMEIRO|\s+SEGUNDO)?)\s+)(?:PER[IÍ]ODO|SEMESTRE|ANO|FASE|TERMO|INTERNATO)|(?:M[OÓ]DULO\s+DO\s+|CICLO\s+DO\s+)?INTERNATO(?:\s+M[EÉ]DICO)?\s*$)[^\n]*)/i);
        if (pMatch && !/\b(?:\d+\s+\d+|\d+\s*h|\d+\s*horas?)\s*$/i.test(line.trim())) {
          blockPeriod = pMatch[1].trim();
        }

        const discMatch = line.match(/^(?:Disciplina|Unidade Curricular|Componente Curricular|M[oó]dulo(?: Curricular)?|Atividade Did[aá]tica|Atividade Curricular|Est[aá]gio(?: Supervisionado)?|Internato(?: M[eé]dico)?)\s*[:\-\.]*\s*(?:([A-Z]{2,6}[\-\s]?\d{2,5}|M\d{3})\s*[:\-\.]*)?\s*(.*)$/i);
        const codePrefixMatch = !discMatch ? line.match(/^([A-Z]{2,6}[\-\s]?\d{2,5}|M\d{3})\s*[:\-\–]\s*([A-Za-zÀ-ÿ].*)$/i) : null;

        if (discMatch || codePrefixMatch) {
          if (currentBlock) addOrUpdateSubject(currentBlock);
          const code = discMatch ? (discMatch[1] || '') : (codePrefixMatch ? codePrefixMatch[1] : '');
          let name = discMatch ? (discMatch[2] ? discMatch[2].trim() : '') : (codePrefixMatch ? codePrefixMatch[2].trim() : '');
          if (!name && lines[i + 1] && !/^(?:Carga|Ementa|S[uú]mula|Bibliografia|Conte[uú]do)/i.test(lines[i + 1])) {
            name = lines[i + 1].trim();
            i++;
          }
          currentBlock = {
            code: code,
            name: code ? `${code} ${name}` : name,
            period: blockPeriod,
            description: '',
            topics: []
          };
          blockSection = 'title';
          continue;
        }

        if (/^(?:Ementa|Conte[uú]do\s+Program[aá]tico|S[uú]mula|Programa\s+da\s+Disciplina|Descri[cç][aã]o)\b/i.test(line)) {
          blockSection = 'ementa';
          const inline = line.replace(/^(?:Ementa|Conte[uú]do\s+Program[aá]tico|S[uú]mula|Programa\s+da\s+Disciplina|Descri[cç][aã]o)\b\s*[:\-\.]*\s*/i, '').trim();
          if (currentBlock && inline) {
            currentBlock.description += (currentBlock.description ? ' ' : '') + inline;
          }
          continue;
        }

        if (/^(?:Bibliografia|Refer[eê]ncias)/i.test(line)) {
          blockSection = 'biblio';
          continue;
        }

        if (/^Carga Horária/i.test(line)) {
          blockSection = 'workload';
          continue;
        }

        if (/^(?:Objetivos|Compet[eê]ncias)/i.test(line)) {
          blockSection = 'objectives';
          continue;
        }

        if (currentBlock && blockSection === 'ementa') {
          // Extrai tópicos com marcadores de lista
          if (/^[\*\•\-\–]\s*/.test(line) || /^\d+[\.\)]\s+/.test(line)) {
            const cleanTopic = line.replace(/^[\*\•\-\–\d\.\)]+\s*/, '').trim();
            if (cleanTopic.length >= 3 && !isGarbageOrBinaryText(cleanTopic)) {
              currentBlock.topics.push(cleanTopic);
            }
          } else {
            currentBlock.description += (currentBlock.description ? ' ' : '') + line;
          }
        }
      }
      if (currentBlock) addOrUpdateSubject(currentBlock);

      // SUB-PARSER 3: Tabelas delimitadas por |, ; ou \t
      if (subjectMap.size === 0) {
        const tableRows = lines.filter(l => (l.includes('|') && l.split('|').length >= 3) || (l.includes(';') && l.split(';').length >= 3) || (l.includes('\t') && l.split('\t').length >= 2));
        if (tableRows.length >= 2) {
          const sep = tableRows[0].includes('|') ? '|' : (tableRows[0].includes(';') ? ';' : '\t');
          for (const row of tableRows) {
            const cols = row.split(sep).map(c => c.trim()).filter(Boolean);
            if (cols.length >= 2) {
              if (!/^(c[oó]digo|disciplina|mat[eé]ria|ementa|per[ií]odo)$/i.test(cols[0])) {
                let candName = cols[0];
                let candDesc = cols.slice(1).join(' ');
                if (/^[A-Z0-9]{2,8}$/i.test(cols[0]) && cols[1]) {
                  candName = cols[0] + ' ' + cols[1];
                  candDesc = cols.slice(2).join(' ');
                }
                addOrUpdateSubject({ name: candName, period: 'Disciplinas da Ementa', description: candDesc, topics: [] });
              }
            }
          }
        }
      }

      // SUB-PARSER 4: Fallback Universal para Listas Simples e Numéricas (até 300 disciplinas)
      if (subjectMap.size === 0) {
        for (const line of lines) {
          if (subjectMap.size >= 300) break;
          const cleanLine = cleanSubjectName(line);
          if (isValidSubjectName(cleanLine)) {
            addOrUpdateSubject({ name: cleanLine, period: '1º Período • Ciclo Básico', description: '', topics: [] });
          }
        }
      }

      return Array.from(subjectMap.values());
    }

    function groupSubjectsIntoCurriculum(subjects) {
      const periodMap = new Map();

      subjects.forEach(subj => {
        const pKey = subj.period || 'Disciplinas da Ementa';
        if (!periodMap.has(pKey)) {
          periodMap.set(pKey, {
            id: 'curriculum_period_' + (periodMap.size + 1),
            period: pKey,
            periodName: pKey,
            cycle: subj.cycle,
            cycleName: subj.cycleName,
            subjects: []
          });
        }
        periodMap.get(pKey).subjects.push(subj);
      });

      const list = Array.from(periodMap.values());

      // Ordenação cronológica perfeita: 1º ao 12º Semestre, depois Optativas e Eletivas
      const romanMap = {
        'XII': 12, 'XI': 11, 'X': 10, 'IX': 9, 'VIII': 8,
        'VII': 7, 'VI': 6, 'V': 5, 'IV': 4, 'III': 3, 'II': 2, 'I': 1
      };
      const getOrder = (p) => {
        const periodStr = p.period || '';
        // 1. Arábico explícito (1 a 12)
        const m = periodStr.match(/\b(1[0-2]|[1-9])\b/);
        if (m) return parseInt(m[1], 10);

        // 2. Numeral Romano
        const rMatch = periodStr.match(/\b(XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\b/i);
        if (rMatch && romanMap[rMatch[1].toUpperCase()]) {
          return romanMap[rMatch[1].toUpperCase()];
        }

        // 3. Regime Anual (1º ao 6º ano)
        const yrMatch = periodStr.match(/\b([1-6])º?\s*ano\b/i);
        if (yrMatch) {
          const yr = parseInt(yrMatch[1], 10);
          return ((yr - 1) * 2) + 1;
        }

        if (/internato/i.test(periodStr)) return 95;
        if (/optativ|eletiv/i.test(periodStr)) return 200;
        return 300;
      };

      list.sort((a, b) => getOrder(a) - getOrder(b));
      return list;
    }

    // =========================================================================
    // MOTOR DE APRENDIZADO & SEQUENCIAMENTO PEDAGÓGICO DE ARQUIVOS (FREE TIER IA)
    // =========================================================================
    // Diretriz: Organizar os slides ou PDFs enviados em ordem lógica de aprendizado
    // que priorize o desenvolvimento e evolução do estudante médico:
    // 1. Bases Morfofuncionais & Fundamentos (Anatomia, Histologia, Biologia Celular)
    // 2. Fisiologia Normal & Homeostase (Funcionamento, Biofísica, Transporte)
    // 3. Patologia Geral & Imunologia (Agressão, Defesa, Inflamação, Microbiologia)
    // 4. Semiologia & Propedêutica Médica (Anamnese, Exame Físico, Lesões Elementares)
    // 5. Fisiopatologia & Afecções Prevalentes (Grandes Síndromes e Doenças)
    // 6. Métodos Diagnósticos & Exames Armados (ECG, Imagem, Laboratório, Biópsias)
    // 7. Farmacologia Racional & Terapêutica (Classes, Posologia, Diretrizes SUS/CFM)
    // 8. Emergência, Casos Clínicos & Internato/ENARE (Condutas Críticas e Casos)
    // 9. Tratados de Referência & Obras Extensas (> 50 MB / Manuais Gerais)
    //
    // Suporta IA Gemini 2.5 Flash no Google AI Studio Free Tier (Custo Zero)
    // com fallback heurístico local imediato, garantindo 100% de disponibilidade.

    const PEDAGOGICAL_PHASES = {
      1: { phase: 1, name: "Bases Morfofuncionais & Fundamentos", icon: "🏛️", rationale: "Fundamentação anatômica, histológica e celular indispensável para a compreensão do sistema." },
      2: { phase: 2, name: "Fisiologia Normal & Homeostase", icon: "⚡", rationale: "Compreensão dos mecanismos fisiológicos normais que mantêm o equilíbrio do órgão/sistema." },
      3: { phase: 3, name: "Patologia Geral & Imunologia", icon: "🛡️", rationale: "Mecanismos moleculares e celulares de agressão, resposta imune e processos inflamatórios." },
      4: { phase: 4, name: "Semiologia & Propedêutica Médica", icon: "🩺", rationale: "Identificação semiológica, anamnese, manobras físicas e reconhecimento de lesões/sinais cardinais." },
      5: { phase: 5, name: "Fisiopatologia & Doenças Prevalentes", icon: "🔬", rationale: "Fisiopatologia clínica das principais afecções e síndromes prevalentes na prática médica." },
      6: { phase: 6, name: "Métodos Diagnósticos & Exames Armados", icon: "📊", rationale: "Interpretação de exames complementares (laboratório, imagem, ECG) e algoritmos diferenciais." },
      7: { phase: 7, name: "Farmacologia & Terapêutica Racional", icon: "💊", rationale: "Manejo terapêutico, classes farmacológicas, veículos, posologias e diretrizes baseadas em evidências." },
      8: { phase: 8, name: "Casos Clínicos, Emergências & ENARE", icon: "🚨", rationale: "Raciocínio clínico integrado, condutas em emergências agudas e resolução de casos de residência." },
      9: { phase: 9, name: "Tratados & Manuais de Referência", icon: "📚", rationale: "Obras extensas de consulta e aprofundamento bibliográfico." }
    };

    function extractExplicitClassNumber(str) {
      if (!str || typeof str !== 'string') return 0;
      const s = str.trim();
      let m = s.match(/\baula[\s_\-]*0*(\d{1,2})\b/i);
      if (m) return parseInt(m[1], 10);
      m = s.match(/\bm[oó]dulo[\s_\-]*0*(\d{1,2})\b/i);
      if (m) return parseInt(m[1], 10);
      m = s.match(/\bparte[\s_\-]*0*(\d{1,2})\b/i);
      if (m) return parseInt(m[1], 10);
      m = s.match(/\bsemana[\s_\-]*0*(\d{1,2})\b/i);
      if (m) return parseInt(m[1], 10);
      m = s.match(/^\s*0*(\d{1,2})\s*[-_.)]/);
      if (m) return parseInt(m[1], 10);
      const romanMatch = s.match(/\b(?:aula|parte|m[oó]dulo)\s*(XII|XI|X|IX|VIII|VII|VI|V|IV|III|II|I)\b/i);
      if (romanMatch) {
        const rMap = { 'I': 1, 'II': 2, 'III': 3, 'IV': 4, 'V': 5, 'VI': 6, 'VII': 7, 'VIII': 8, 'IX': 9, 'X': 10, 'XI': 11, 'XII': 12 };
        return rMap[romanMatch[1].toUpperCase()] || 0;
      }
      return 0;
    }

    function classifyPedagogicalPhase(text, sizeMB, isBook) {
      if (isBook || (sizeMB && sizeMB > 50)) return PEDAGOGICAL_PHASES[9];
      const s = (text || '').toLowerCase();

      // Fase 9: Tratados e Obras Extensas
      if (/\b(tratado|livro[\s_\-]*texto|manual\s*completo|harrison|cecil|guyton|robbins|azulay)/i.test(s)) {
        return PEDAGOGICAL_PHASES[9];
      }

      // Fase 8: Casos Clínicos, Emergências, UTI & Questões ENARE
      if (/\b(caso\s*cl[íi]nico|casos\s*cl[íi]nicos|discuss[aã]o\s*cl[íi]nica|vinheta|urg[êe]ncia|emerg[êe]ncia|choque|parada|\bpcr\b|atls|acls|intuba[çc]|\biot\b|ressuscita|enare|revalida|resid[êe]ncia|pronto\s*socorro|\buti\b)/i.test(s)) {
        return PEDAGOGICAL_PHASES[8];
      }

      // Fase 7: Farmacologia & Terapêutica Racional
      if (/\b(f[aá]rmaco|terap[êe]utic|medicament|farmacocin|farmacodin|prescri[çc]|posolog|droga|mecanismo\s*de\s*a[çc][aã]o|cortic[oó]ide|antibiot|antimicrobian|antifung|antiviral|anti-hipertens|diur[ée]tic|betabloqueador|\bieca\b|\bbra\b|antiinflamat|analg[ée]sic|imunobiol|ve[íi]culo|pomada|creme|lo[çc][aã]o|gel|pcdt|diretriz\s*terap[êe]utica|protocolo\s*de\s*tratamento)/i.test(s)) {
        return PEDAGOGICAL_PHASES[7];
      }

      // Fase 6: Métodos Diagnósticos, Exames Complementares & Diagnóstico Diferencial
      if (/\b(diagn[oó]stic|exame.*complementar|propedeut.*armada|laborat|\becg\b|eletrocardio|raio.*x|radiograf|tomograf|\btc\b|resson[âa]nc|\brm\b|ultrassom|\busg\b|ecocardio|bi[oó]psia|histopatolog|imunofluoresc|espirometria|endoscopia|sorolog|gasometria|troponina|\bbnp\b|diagn[oó]stico\s*diferencial|esquemas\s*diagn[oó]sticos|algoritmo)/i.test(s)) {
        return PEDAGOGICAL_PHASES[6];
      }

      // Fase 4: Semiologia & Propedêutica Médica
      if (/\b(semiolog|proped[êe]ut|anamnese|exame\s*f[íi]sico|inspe[çc]|palpa[çc]|percuss|auscult|les[oõ]es?\s*elementar|m[aá]cul|p[aá]pul|ves[íi]cul|bolha|p[uú]stul|sinais\s*vitais|semiog[êe]nese|manobra|auspitz|nikolsky|darier|koebner|bulha|sopro|estridor|crepit)/i.test(s)) {
        return PEDAGOGICAL_PHASES[4];
      }

      // Fase 1: Bases Morfofuncionais, Introdução e Histologia
      if (/\b(introdu[çc]|apresenta[çc]|plano\s*de\s*aula|cronograma|ementa|conceit|fundament|anatom|morfolog|embrio|histolog|citolog|biolog.*celular|gen[ée]tic|ultraestrutur|tecido|epit[ée]l|endot[ée]l|epiderm|derme|camada\s*basal|queratin[oó]cit|melan[oó]cit|osteolog|miolog|neuroanatom)/i.test(s)) {
        return PEDAGOGICAL_PHASES[1];
      }

      // Fase 2: Fisiologia Normal & Homeostase
      if (/\b(fisiolog|homeostas|eletrofisiolog|biof[íi]sic|transporte|potencial\s*de\s*a[çc][aã]o|receptores|sinapse|ciclo\s*card[íi]aco|d[ée]bito|hemodin[âa]mic|troca\s*gasosa|ventila[çc]|perfus|filtra[çc]|hemostas|barreira\s*cut[âa]nea|fun[çc][aã]o\s*renal)/i.test(s)) {
        return PEDAGOGICAL_PHASES[2];
      }

      // Fase 3: Patologia Geral & Imunologia
      if (/\b(imunolog|resposta\s*imune|ant[íi]gen|anticorp|linf[oó]cit|citocin|interleucin|inflama[çc]|microbiolog|bacteriolog|virolog|parasitolog|micolog|fung|v[íi]rus|bact[ée]ri|patolog.*geral|necrose|apoptose|cicatriza[çc]|isquemi|aterog[êe]n)/i.test(s)) {
        return PEDAGOGICAL_PHASES[3];
      }

      // Fase 5: Fisiopatologia das Doenças Prevalentes (Default clínico)
      return PEDAGOGICAL_PHASES[5];
    }

    function findSyllabusTopicIndex(combinedText, subjectName) {
      if (!combinedText || !subjectName) return -1;
      const c = combinedText.toLowerCase();
      const sLower = subjectName.toLowerCase();

      if (typeof universityCurriculum !== 'undefined' && Array.isArray(universityCurriculum)) {
        for (const p of universityCurriculum) {
          if (p.subjects && Array.isArray(p.subjects)) {
            const match = p.subjects.find(s => {
              const name = typeof s === 'string' ? s : s.name;
              return name && (name.toLowerCase().includes(sLower) || sLower.includes(name.toLowerCase()));
            });
            if (match && match.topics && Array.isArray(match.topics)) {
              for (let i = 0; i < match.topics.length; i++) {
                const topic = match.topics[i].toLowerCase();
                const words = topic.split(/\s+/).filter(w => w.length > 3);
                if (words.some(w => c.includes(w))) {
                  return i;
                }
              }
            }
          }
        }
      }
      return -1;
    }

    // O título e o índice descritivo são sinais mais confiáveis do objetivo de uma aula
    // que uma palavra isolada perdida em um PDF clínico extenso. Este perfil permite
    // sequenciar a matéria a partir do material salvo, sem depender da ordem de upload.
    const PEDAGOGICAL_PHASE_EVIDENCE = {
      1: /\b(anatom|morfolog|histolog|embriolog|citolog|biologia\s+celular|tecido|estrutura|camadas?|topografia|neuroanatom|osteolog|miolog)\w*/gi,
      2: /\b(fisiolog|homeostas|fun[cç][aã]o\s+normal|biof[ií]sic|transporte|receptor|sinapse|potencial\s+de\s+a[cç][aã]o|ventila[cç][aã]o|perfus[aã]o|filtra[cç][aã]o)\w*/gi,
      3: /\b(imunolog|inflama[cç][aã]o|resposta\s+imune|citocin|anticorp|linf[oó]cit|microbiolog|patologia\s+geral|necrose|apoptose|agress[aã]o)\w*/gi,
      4: /\b(semiolog|proped[eê]ut|anamnese|exame\s+f[ií]sico|inspe[cç][aã]o|palpa[cç][aã]o|ausculta|percuss[aã]o|sinais?\s+e\s+sintomas?|les[oõ]es?\s+elementares?)\w*/gi,
      5: /\b(fisiopatolog|doen[cç]a|s[ií]ndrome|etiologia|causa|manifesta[cç][aã]o|complica[cç][aã]o|consequ[eê]ncia|preval[eê]ncia)\w*/gi,
      6: /\b(diagn[oó]stic|exames?\s+complementares?|laborat[oó]rio|tomografia|resson[âa]ncia|radiografia|ultrassom|ecg|ecocardi|bi[oó]psia|diagn[oó]stico\s+diferencial|algoritmo)\w*/gi,
      7: /\b(tratamento|terap[êe]utic|f[aá]rmaco|medicamento|posologia|prescri[cç][aã]o|antibi[oó]tico|corticoide|diretriz|protocolo\s+terap[êe]utico)\w*/gi,
      8: /\b(caso\s+cl[ií]nico|vinheta|emerg[eê]ncia|urg[eê]ncia|pronto\s+socorro|uti|enare|revalida|resid[eê]ncia|conduta\s+imediata|choque|atls|acls)\w*/gi
    };

    function getMaterialPedagogicalText(material) {
      const index = material.descriptiveIndex || {};
      const sections = Array.isArray(index.sections) ? index.sections.map(section => `${section.title || ''} ${section.description || ''}`).join(' ') : '';
      const concepts = Array.isArray(index.keyConcepts) ? index.keyConcepts.join(' ') : '';
      const title = `${material.name || material.originalFileName || ''} ${material.topic || ''} ${material.disease || ''}`;
      const body = (material.text || material.readingDocText || '').slice(0, 12000);
      return { title, full: `${title} ${material.desc || ''} ${material.folderPath || ''} ${concepts} ${sections} ${body}` };
    }

    function countPedagogicalEvidence(text, expression) {
      if (!text || !expression) return 0;
      const flags = expression.flags.includes('g') ? expression.flags : `${expression.flags}g`;
      const matches = text.match(new RegExp(expression.source, flags));
      return matches ? matches.length : 0;
    }

    function buildMaterialPedagogicalProfile(material, subjectContext) {
      const { title, full } = getMaterialPedagogicalText(material);
      const sizeMB = material.sizeMB || (material.file ? material.file.size / (1024 * 1024) : 0);
      const isBook = material.isBook || material.type === 'book' || sizeMB > 50;
      const normalizedTitle = title.toLowerCase();
      const phaseEvidence = {};

      for (let phase = 1; phase <= 8; phase++) {
        // Título e índice recebem peso maior: são a intenção pedagógica da aula.
        phaseEvidence[phase] = countPedagogicalEvidence(full, PEDAGOGICAL_PHASE_EVIDENCE[phase])
          + (countPedagogicalEvidence(normalizedTitle, PEDAGOGICAL_PHASE_EVIDENCE[phase]) * 4);
      }

      let phase = 5;
      if (isBook || /\b(tratado|livro[\s_-]*texto|manual\s+completo|harrison|cecil|guyton|robbins|azulay)\b/i.test(normalizedTitle)) {
        phase = 9;
      } else {
        phase = Object.keys(phaseEvidence).reduce((best, candidate) =>
          phaseEvidence[candidate] > phaseEvidence[best] ? Number(candidate) : best, 5);
        // Sem evidência suficiente: mantém a classificação legada, mas não deixa uma
        // única menção clínica em aula básica determinar o resultado.
        if ((phaseEvidence[phase] || 0) < 2) {
          phase = classifyPedagogicalPhase(`${title} ${(material.descriptiveIndex?.summaryText || '')}`, sizeMB, isBook).phase;
        }
      }

      const explicitClassNumber = extractExplicitClassNumber(material.name || material.originalFileName || '');
      const syllabusIndex = findSyllabusTopicIndex(full, subjectContext || material.subject);
      const startsWithFoundation = /\b(introdu[cç][aã]o|vis[aã]o\s+geral|fundamentos?|bases?|conceitos?\s+b[aá]sicos?|parte\s+1|aula\s+1)\b/i.test(normalizedTitle);
      const isContinuation = /\b(continua[cç][aã]o|aprofundamento|avan[cç]ado|parte\s+[2-9]|revis[aã]o|casos?)\b/i.test(normalizedTitle);
      const phaseDef = PEDAGOGICAL_PHASES[phase];

      return {
        phase,
        phaseDef,
        phaseEvidence,
        explicitClassNumber,
        syllabusIndex,
        startsWithFoundation,
        isContinuation,
        concepts: (material.descriptiveIndex?.keyConcepts || []).slice(0, 6),
        confidence: Math.min(100, (phaseEvidence[phase] || 0) * 12)
      };
    }

    function calculatePedagogicalScore(material, subjectContext) {
      const profile = buildMaterialPedagogicalProfile(material, subjectContext);
      const { phaseDef, explicitClassNumber, syllabusIndex } = profile;
      // Mantém um escore estável para integrações legadas; a ordenação final usa
      // também os critérios do perfil, evitando que o nome do arquivo prevaleça.
      let score = phaseDef.phase * 10000;
      score += syllabusIndex >= 0 ? syllabusIndex * 100 : 50;
      score += explicitClassNumber > 0 ? explicitClassNumber : 50;
      score += profile.startsWithFoundation ? -20 : (profile.isContinuation ? 20 : 0);

      material.pedagogicalPhase = phaseDef.phase;
      material.pedagogicalPhaseName = phaseDef.name;
      material.pedagogicalIcon = phaseDef.icon;
      material.pedagogicalRationale = `${phaseDef.rationale} ${profile.syllabusIndex >= 0 ? 'A posição também respeita o tópico correspondente na ementa.' : 'A posição foi inferida pelo título, índice e conceitos do próprio material.'}`;
      material.pedagogicalScore = score;
      material.pedagogicalProfile = profile;
      if (!material.sequencingEngine) {
        material.sequencingEngine = 'Motor didático local por conteúdo salvo';
      }

      return score;
    }

    function sortMaterialsInPedagogicalOrder(materialsList, subjectContext) {
      if (!materialsList || !Array.isArray(materialsList)) return [];
      if (materialsList.length <= 1) {
        if (materialsList.length === 1) {
          calculatePedagogicalScore(materialsList[0], subjectContext);
          materialsList[0].learningOrder = 1;
          materialsList[0].totalStepsInSubject = 1;
        }
        return materialsList;
      }

      const copy = materialsList.slice();
      copy.forEach(m => calculatePedagogicalScore(m, subjectContext));

      copy.sort((a, b) => {
        const pa = a.pedagogicalProfile;
        const pb = b.pedagogicalProfile;
        if (pa.phase !== pb.phase) return pa.phase - pb.phase;
        // Dentro da mesma etapa, a ementa explícita organiza o encadeamento; na
        // ausência dela, usa-se a numeração da aula e por fim a prontidão didática.
        if (pa.syllabusIndex >= 0 && pb.syllabusIndex >= 0 && pa.syllabusIndex !== pb.syllabusIndex) {
          return pa.syllabusIndex - pb.syllabusIndex;
        }
        if (pa.explicitClassNumber && pb.explicitClassNumber && pa.explicitClassNumber !== pb.explicitClassNumber) {
          return pa.explicitClassNumber - pb.explicitClassNumber;
        }
        if (pa.startsWithFoundation !== pb.startsWithFoundation) return pa.startsWithFoundation ? -1 : 1;
        if (pa.isContinuation !== pb.isContinuation) return pa.isContinuation ? 1 : -1;
        return (a.pedagogicalScore || 0) - (b.pedagogicalScore || 0)
          || String(a.name || a.originalFileName || '').localeCompare(String(b.name || b.originalFileName || ''), 'pt-BR');
      });

      copy.forEach((m, idx) => {
        m.learningOrder = idx + 1;
        m.totalStepsInSubject = copy.length;
        m.pedagogicalBadge = `<span class="learning-step-pill">${m.pedagogicalIcon || '🎯'} Passo ${m.learningOrder}: ${m.pedagogicalPhaseName}</span>`;
      });

      return copy;
    }

    function sortChatDriveMaterialsInLearningOrder() {
      if (typeof chatDriveMaterials === 'undefined' || !Array.isArray(chatDriveMaterials) || chatDriveMaterials.length <= 1) return;
      const groups = {};
      chatDriveMaterials.forEach(m => {
        const s = m.subject || 'Geral';
        if (!groups[s]) groups[s] = [];
        groups[s].push(m);
      });

      const reordered = [];
      Object.keys(groups).forEach(s => {
        const sorted = sortMaterialsInPedagogicalOrder(groups[s], s);
        reordered.push(...sorted);
      });

      chatDriveMaterials = reordered;
      if (typeof window !== 'undefined') window.chatDriveMaterials = chatDriveMaterials;
    }

    // INTEGRAÇÃO COM MOTOR IA FREE TIER (GEMINI 2.5 FLASH / CUSTO ZERO)
    async function organizeMaterialsViaGeminiFreeTier(materialsList, subjectContext, forceAi = false) {
      if (!materialsList || !Array.isArray(materialsList) || materialsList.length === 0) return [];
      
      // 1. Aplica a ordenação heurística local como base instantânea
      let ordered = sortMaterialsInPedagogicalOrder(materialsList, subjectContext);

      const apiKey = (typeof getGeminiApiKey === 'function') ? getGeminiApiKey() : '';
      const hasMock = (typeof window !== 'undefined' && window.__mockGeminiSequencing);
      
      if (!apiKey && !hasMock) {
        return ordered;
      }

      if (!forceAi && ordered.every(m => m.aiSequenced === true)) {
        return ordered;
      }

      try {
        const candidateMaterials = ordered.map((m, idx) => ({
          id: m.id || `mat_${idx}`,
          name: m.name || m.originalFileName || `Material ${idx + 1}`,
          disease: m.disease || '',
          topic: m.topic || '',
          desc: m.desc || '',
          sample: (m.text || m.readingDocText || '').slice(0, 300)
        }));

        let syllabusTopics = [];
        if (typeof universityCurriculum !== 'undefined' && Array.isArray(universityCurriculum)) {
          for (const p of universityCurriculum) {
            if (p.subjects && Array.isArray(p.subjects)) {
              const s = p.subjects.find(sub => {
                const subName = typeof sub === 'string' ? sub : sub.name;
                return subName && subjectContext && subName.toLowerCase().includes(subjectContext.toLowerCase());
              });
              if (s && s.topics) {
                syllabusTopics = Array.isArray(s.topics) ? s.topics : [s.topics];
                break;
              }
            }
          }
        }

        const promptText = `Você é um preceptor médico e coordenador pedagógico especialista em educação médica e nas Diretrizes Curriculares Nacionais (DCNs do MEC).
Sua missão é organizar os seguintes ${candidateMaterials.length} materiais didáticos (slides e PDFs) da disciplina "${subjectContext || 'Medicina'}" na ORDEM PEDAGÓGICA IDEAL DE APRENDIZADO para um estudante de medicina, priorizando o desenvolvimento cognitivo e a evolução clínica contínua.

Ementa oficial da disciplina (tópicos de referência):
${syllabusTopics.length > 0 ? syllabusTopics.map((t, i) => `${i + 1}. ${t}`).join('\n') : 'Considere a sequência clássica da medicina brasileira.'}

Lista de materiais a sequenciar:
${JSON.stringify(candidateMaterials, null, 2)}

DIRETRIZES RÍGIDAS DE SEQUENCIAMENTO PEDAGÓGICO DE APRENDIZADO:
1. Fase 1: Bases Morfofuncionais (Anatomia, Histologia, Embriologia, Biologia Celular da pele/órgão)
2. Fase 2: Fisiologia Normal e Homeostase (Mecanismos fisiológicos normais e biofísica)
3. Fase 3: Patologia Geral e Imunologia (Mecanismos de agressão, inflamação e resposta imune)
4. Fase 4: Semiologia e Propedêutica (Anamnese, exame físico, manobras, lesões elementares)
5. Fase 5: Fisiopatologia das Afecções Prevalentes (Doenças mais comuns e prevalentes)
6. Fase 6: Métodos Diagnósticos e Armada (ECG, exames complementares, diagnóstico diferencial)
7. Fase 7: Farmacologia e Terapêutica Racional (Classes farmacológicas, posologia, diretrizes)
8. Fase 8: Casos Clínicos, Emergências e Residência (Tomada de decisão crítica, ENARE, internato)
9. Fase 9: Tratados e Obras Extensas de Referência (Manuais e livros de consulta)

Para cada material, retorne um objeto no JSON com:
- "id": ID exato do material
- "step": Número de ordem do passo de estudo (inteiro de 1 a ${candidateMaterials.length}, sem repetir números)
- "phase": Número da fase pedagógica (1 a 9)
- "phaseName": Nome curto da fase (ex: "Bases Morfofuncionais", "Semiologia & Propedêutica", "Farmacologia")
- "icon": Emoji temático ("🏛️", "⚡", "🛡️", "🩺", "🔬", "📊", "💊", "🚨", "📚")
- "rationale": Breve justificativa de 1 frase explicando por que esta aula deve ser estudada nesta etapa da evolução clínica.`;

        const payload = {
          contents: [{ parts: [{ text: promptText }] }],
          generationConfig: {
            temperature: 0.1,
            maxOutputTokens: 2048,
            responseMimeType: "application/json",
            responseSchema: {
              type: "ARRAY",
              items: {
                type: "OBJECT",
                properties: {
                  id: { type: "STRING" },
                  step: { type: "INTEGER" },
                  phase: { type: "INTEGER" },
                  phaseName: { type: "STRING" },
                  icon: { type: "STRING" },
                  rationale: { type: "STRING" }
                },
                required: ["id", "step", "phase", "phaseName", "rationale"]
              }
            }
          }
        };

        let aiResult = null;

        if (hasMock) {
          aiResult = await window.__mockGeminiSequencing(candidateMaterials, subjectContext);
        } else {
          const models = (typeof GEMINI_CONFIG_2026 !== 'undefined' && GEMINI_CONFIG_2026.models) 
            ? GEMINI_CONFIG_2026.models 
            : ['gemini-3.5-flash'];

          for (const model of models) {
            try {
              const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey.trim())}`;
              const res = await fetch(url, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(payload)
              });
              if (!res.ok) continue;
              const data = await res.json();
              const textContent = data.candidates?.[0]?.content?.parts?.[0]?.text;
              if (textContent) {
                aiResult = JSON.parse(textContent);
                if (Array.isArray(aiResult) && aiResult.length > 0) {
                  if (typeof AppExpenseTracker !== 'undefined') {
                    AppExpenseTracker.recordExpense({
                      tokensIn: data.usageMetadata?.promptTokenCount || 400,
                      tokensOut: data.usageMetadata?.candidatesTokenCount || 300,
                      modelKey: model,
                      actionName: 'Sequenciamento Pedagógico de Aprendizado (Gemini Free Tier)'
                    });
                  }
                  break;
                }
              }
            } catch (errLoop) {
              console.warn(`Tentativa com ${model} falhou:`, errLoop);
            }
          }
        }

        if (Array.isArray(aiResult) && aiResult.length > 0) {
          const mapById = {};
          aiResult.forEach(item => {
            if (item.id) mapById[item.id] = item;
          });

          ordered.forEach(m => {
            const aiMeta = mapById[m.id];
            if (aiMeta) {
              m.learningOrder = aiMeta.step;
              m.pedagogicalPhase = aiMeta.phase;
              m.pedagogicalPhaseName = aiMeta.phaseName;
              m.pedagogicalIcon = aiMeta.icon || '🎯';
              m.pedagogicalRationale = aiMeta.rationale;
              m.aiSequenced = true;
              m.sequencingEngine = 'Gemini 2.5 Flash (Free Tier)';
            }
          });

          ordered.sort((a, b) => (a.learningOrder || 999) - (b.learningOrder || 999));
          ordered.forEach((m, idx) => {
            m.learningOrder = idx + 1;
            m.totalStepsInSubject = ordered.length;
          });

          if (typeof saveChatDriveMaterials === 'function') {
            saveChatDriveMaterials();
          }
        }
      } catch (aiErr) {
        console.warn('Fallback para motor heurístico local:', aiErr);
      }

      return ordered;
    }

