      const qMedio1 = createMedicalQuestionObject(topicName + ' - Mecanismos Fisiopatológicos e Vias', targetSubj, 2, { difficulty: 'intermediario' });
      const qMedio2 = createMedicalQuestionObject(topicName + ' - Correlação Semiológica e Déficits', targetSubj, 3, { difficulty: 'intermediario' });
