    /**
     * Analisador pericial de Apostila / Caderno de Questões
     */
    function parseChatBookletData(rawText, bookletTitle, subjectName, material = null) {
      const bookletId = 'bkl-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6);
      const text = rawText || '';
      const subject = subjectName || (material && (material.subject || material.disciplina)) || currentStudySubject || 'Medicina';

      const questionsList = [];
      const flashcardsList = [];

      // Extrai o gabarito comentado se presente
      const gabaritoMap = {};
      const gabaritoRegex = /(?:Quest[aã]o|Questao|\bQ\b)\s*(\d+)[:\s\-–]*(?:Alternativa|Resposta|Letra)?\s*\*?\*?([A-E])\*?\*?([^\n]*)/gi;
      let gMatch;
      while ((gMatch = gabaritoRegex.exec(text)) !== null) {
        const qNum = parseInt(gMatch[1], 10);
        const letter = gMatch[2].toUpperCase();
        const snippet = gMatch[3] ? gMatch[3].trim() : '';
        gabaritoMap[qNum] = {
          correctIndex: letter.charCodeAt(0) - 65,
          snippet: snippet
        };
      }

      // Extrai questões de múltipla escolha
      const qBlocks = text.split(/(?=(?:###|\*\*|##)?\s*(?:Quest[aã]o\s+\d+|Questão|\b\d+\.\s+))/i);

      qBlocks.forEach((block, bIdx) => {
        const hasOptions = /\[\s*\]\s*[A-E]\)|(?:^|\n)\s*[A-E]\)\s+/m.test(block);
        if (!hasOptions) return;

        let level = 'fácil';
        const lowerB = block.toLowerCase();
        if (lowerB.includes('módulo 3') || lowerB.includes('avançado') || lowerB.includes('caso clínico') || bIdx >= 6) {
          level = 'avançado';
        } else if (lowerB.includes('módulo 2') || lowerB.includes('intermediário') || lowerB.includes('fisiopatologia') || bIdx >= 3) {
          level = 'intermediário';
        }

        const lines = block.split('\n').map(l => l.trim()).filter(Boolean);
        let qPrompt = '';
        let vignette = '';
        const options = [];

        lines.forEach(line => {
          const optMatch = line.match(/^(?:\[\s*\]\s*)?([A-E]\))\s*(.*)$/i);
          if (optMatch) {
            options.push(optMatch[2].trim());
          } else if (line.toLowerCase().includes('vinheta') || line.toLowerCase().includes('caso clínico:')) {
            vignette += line.replace(/^(?:\*|\*\*|#)?\s*(?:Vinheta Clínica|Caso Clínico)[:\s]*/i, '') + ' ';
          } else if (!line.startsWith('#') && !line.startsWith('---') && options.length === 0) {
            const cleanL = line.replace(/^\*{1,2}Quest[aã]o\s*\d+[^:]*:\*{1,2}\s*/i, '').replace(/^\d+\.\s*/, '');
            if (cleanL.length > 5) {
              qPrompt += cleanL + ' ';
            }
          }
        });

        if (options.length >= 2) {
          const qId = `q-${bookletId}-${questionsList.length + 1}`;
          const qNum = questionsList.length + 1;
          const gab = gabaritoMap[qNum] || { correctIndex: 0 };

          questionsList.push({
            id: qId,
            bookletId: bookletId,
            qNum: qNum,
            level: level,
            vignette: vignette.trim(),
            question: qPrompt.trim() || `Questão sobre ${bookletTitle}`,
            options: options.slice(0, 5),
            correctIndex: (gab.correctIndex >= 0 && gab.correctIndex < options.length) ? gab.correctIndex : 0,
            explanation: gab.snippet || 'Conforme diretrizes clínicas e fundamentos anatômicos canônicos.',
            tripartite: {
              correctReason: gab.snippet || 'Fundamentação clínica pelas diretrizes de referência.',
              distractorAnalysis: {},
              pearl: 'A identificação semiológica precoce e o diagnóstico topográfico correto norteiam a conduta médica resolutiva.'
            }
          });
        }
      });

      // Extrai Flashcards
      const fcRegex = /(?:Card\s*(\d+)|[-*]\s*\*\*Card\s*\d+)[^\n]*Frente:\*?\*?\s*([^\n]+)[\s\S]*?Verso:\*?\*?\s*([^\n]+(?:\n(?!\s*[-*]\s*\*\*?Card)[^\n]+)*)/gi;
      let fcMatch;
      while ((fcMatch = fcRegex.exec(text)) !== null) {
        const front = fcMatch[2].replace(/\*\*/g, '').trim();
        const back = fcMatch[3].replace(/\*\*/g, '').trim();
        if (front.length > 5 && back.length > 3) {
          flashcardsList.push({
            id: `fc-${bookletId}-${flashcardsList.length + 1}`,
            front: front,
            back: back,
            category: flashcardsList.length < 2 ? 'Anatomia Básica' : (flashcardsList.length < 4 ? 'Fisiopatologia' : 'Conduta ENARE')
          });
        }
      }

      if (questionsList.length < 3 || flashcardsList.length < 2) {
        const localEnrichment = generateLocalQuestionBooklet({
          topic: bookletTitle,
          subject: subject,
          material: material
        });

        if (questionsList.length < 3) {
          localEnrichment.questions.forEach((q, idx) => {
            if (questionsList.length < 6) {
              questionsList.push({
                id: `q-${bookletId}-${questionsList.length + 1}`,
                bookletId: bookletId,
                qNum: questionsList.length + 1,
                level: idx < 2 ? 'fácil' : (idx < 4 ? 'intermediário' : 'avançado'),
                vignette: q.vignette || '',
                question: q.question,
                options: q.quizOptions || [],
                correctIndex: q.correctIndex || 0,
                explanation: q.explanation || '',
                tripartite: q.tripartite || { pearl: 'Atenção aos marcos anatômicos e conduta SUS.' }
              });
            }
          });
        }

        if (flashcardsList.length < 2) {
          flashcardsList.push(
            { id: `fc-${bookletId}-1`, front: `O que caracteriza a estrutura de ${bookletTitle}?`, back: `Identificação topográfica anatômica com marcos de referência canônicos.`, category: 'Anatomia Básica' },
            { id: `fc-${bookletId}-2`, front: `Onde fica situado o sítio anatômico de ${bookletTitle}?`, back: `Posicionamento anatômico contíguo com núcleos e feixes vasculonervosos.`, category: 'Anatomia Básica' },
            { id: `fc-${bookletId}-3`, front: `Qual a via fisiopatológica e sinal semiológico de ${bookletTitle}?`, back: `Comprometimento funcional característico com correlação semiológica direta.`, category: 'Fisiopatologia' },
            { id: `fc-${bookletId}-4`, front: `Qual a conduta resolutiva e prioridade de manejo para ${bookletTitle}?`, back: `Estabilização imediata e seguimento conforme diretrizes do PCDT/SUS.`, category: 'Conduta ENARE' }
          );
        }
      }

      const formattedHtml = (typeof formatAITextToHTML === 'function') ? formatAITextToHTML(text) : text;

      return {
        id: bookletId,
        title: bookletTitle,
        subject: subject,
        rawText: text,
        formattedHtml: formattedHtml,
        allQuizQuestions: questionsList,
        flashcards: flashcardsList,
        stats: {
          totalQuestions: questionsList.length,
          answered: 0,
          correct: 0,
          userChoices: {}
        },
        activeTab: 'apostila',
        currentFlashcardIndex: 0,
        flashcardFlipped: false,
        savedToSubject: false,
        savedSubjectName: null,
        createdAt: new Date().toISOString()
      };
    }

    /**
     * Renderiza o Card de Apostila no Chat com Abas e Ações
     */
    function renderChatBookletCardHtml(bookletId) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet) return '';

      const qCount = booklet.allQuizQuestions.length;
      const fcCount = booklet.flashcards.length;

      const quizItemsHtml = booklet.allQuizQuestions.map((q, idx) => {
        const levelClass = q.level === 'fácil' ? 'facil' : (q.level === 'intermediário' ? 'medio' : 'dificil');
        const levelLabel = q.level === 'fácil' ? '🟢 Nível Fácil: Reconhecimento Anatômico' : (q.level === 'intermediário' ? '🟡 Nível Médio: Fisiopatologia' : '🔴 Nível Avançado: Caso Clínico ENARE');

        return `
          <div class="chat-quiz-item" id="bkl-qitem-${q.id}">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
              <span class="chat-quiz-level-badge ${levelClass}">
                ${levelLabel}
              </span>
              <span style="font-size: 11px; font-weight: 700; color: var(--text-muted);">
                #${idx + 1}
              </span>
            </div>

            ${q.vignette ? `
              <div class="quiz-vignette-box" style="margin-bottom: 8px; background: rgba(0, 0, 0, 0.2); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 8px; padding: 8px 10px;">
                <strong style="color: #38bdf8; font-size: 11px; text-transform: uppercase; display: block; margin-bottom: 4px;">
                  📋 Caso Clínico & História:
                </strong>
                ${(typeof formatInlineMd === 'function') ? formatInlineMd(q.vignette) : q.vignette}
              </div>
            ` : ''}

            <div style="font-size: 13.5px; font-weight: 600; line-height: 1.5; margin-bottom: 12px; color: var(--text-primary);">
              ${(typeof formatInlineMd === 'function') ? formatInlineMd(q.question) : q.question}
            </div>

            <div class="quiz-options-list" id="bkl-opts-${q.id}">
              ${q.options.map((opt, optIdx) => `
                <div class="quiz-opt" id="bkl-opt-${q.id}-${optIdx}" onclick="answerChatBookletQuizOption('${bookletId}', '${q.id}', ${optIdx})">
                  <span style="font-weight: 700; width: 22px; flex-shrink: 0;">${String.fromCharCode(65 + optIdx)})</span>
                  <span style="flex: 1;">${(typeof formatInlineMd === 'function') ? formatInlineMd(opt) : opt}</span>
                </div>
              `).join('')}
            </div>

            <div class="chat-quiz-feedback" id="bkl-feedback-${q.id}"></div>
          </div>
        `;
      }).join('');

      const firstFc = booklet.flashcards[0] || { front: 'Sem cartões', back: 'Sem cartões' };

      return `
        <div class="chat-booklet-card" id="bkl-card-${bookletId}">
          <div class="booklet-info">
            <div class="booklet-icon-badge">📘</div>
            <div style="flex: 1; min-width: 0;">
              <span class="booklet-badge-tag">Apostila de Questões • Progressão Gradual (Fácil ➔ ENARE)</span>
              <h4 class="booklet-main-title">${escapeHtml(booklet.title)}</h4>
              <div class="booklet-meta-line">
                ${qCount} Questões (Fácil, Intermediário, Casos Clínicos) • ${fcCount} Flashcards • Padrão A4 & Interativo
              </div>
            </div>
          </div>

          <div class="booklet-actions">
            <button class="btn-booklet-emit" onclick="emitChatBookletPdf('${bookletId}')" title="Emitir apostila completa em PDF A4 com caixas ☐ e linhas de escrita manual">
              🖨️ Imprimir Apostila (A4)
            </button>
            <button class="btn-booklet-save" id="bkl-btn-save-${bookletId}" onclick="openSaveBookletToSubjectModal('${bookletId}')" title="Salvar questões e flashcards no banco geral de uma matéria">
              ${booklet.savedToSubject ? `✅ Salvo em: ${escapeHtml(booklet.savedSubjectName)}` : '📥 Salvar na Disciplina...'}
            </button>
            <button class="btn-booklet-copy" onclick="copyChatBookletText('${bookletId}')" title="Copiar texto da apostila">
              📋 Copiar Apostila
            </button>
          </div>

          <!-- Abas de Alternância Rápida -->
          <div class="chat-booklet-tabs">
            <button class="chat-booklet-tab active" data-tab="apostila" onclick="selectChatBookletTab('${bookletId}', 'apostila')">
              📑 Apostila Completa
            </button>
            <button class="chat-booklet-tab" data-tab="quiz" onclick="selectChatBookletTab('${bookletId}', 'quiz')">
              ⚡ Quiz Interativo (${qCount})
            </button>
            <button class="chat-booklet-tab" data-tab="flashcards" onclick="selectChatBookletTab('${bookletId}', 'flashcards')">
              🗂️ Flashcards (${fcCount})
            </button>
          </div>

          <!-- Conteúdo da Aba 1: Apostila Completa -->
          <div class="chat-booklet-pane active" id="bkl-pane-apostila-${bookletId}" data-pane="apostila" style="font-size: 13.5px; line-height: 1.6;">
            <div style="background: rgba(0, 0, 0, 0.15); border: 1px solid rgba(255, 255, 255, 0.07); border-radius: 10px; padding: 16px; margin-top: 8px;">
              ${booklet.formattedHtml}
            </div>
          </div>

          <!-- Conteúdo da Aba 2: Quiz Interativo -->
          <div class="chat-booklet-pane" id="bkl-pane-quiz-${bookletId}" data-pane="quiz">
            <div class="chat-quiz-tracker-bar" id="bkl-tracker-${bookletId}">
              <span>Progresso: <strong>0/${qCount} respondidas</strong></span>
              <span>Acertos: <strong id="bkl-score-${bookletId}">0 (0%)</strong></span>
            </div>
            ${quizItemsHtml}
          </div>

          <!-- Conteúdo da Aba 3: Flashcards -->
          <div class="chat-booklet-pane" id="bkl-pane-flashcards-${bookletId}" data-pane="flashcards">
            <div class="chat-flashcard-widget">
              <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; font-size: 11.5px; color: var(--text-muted);">
                <span>Progresso: Flashcard <strong id="bkl-fc-num-${bookletId}">1</strong> de <strong>${fcCount}</strong></span>
                <span style="color: #10b981; font-weight: 700;">Fixação Ativa</span>
              </div>

              <div class="chat-flashcard-inner" id="bkl-fc-card-${bookletId}" onclick="flipChatBookletFlashcard('${bookletId}')">
                <div id="bkl-fc-front-${bookletId}" style="display: flex; flex-direction: column; justify-content: space-between; height: 100%;">
                  <div>
                    <span style="display: inline-block; font-size: 10px; font-weight: 700; color: #10b981; background: rgba(16, 185, 129, 0.15); padding: 2px 7px; border-radius: 4px; margin-bottom: 10px;">
                      ❓ PERGUNTA / CONCEITO
                    </span>
                    <div style="font-size: 14.5px; font-weight: 600; line-height: 1.5; color: var(--text-primary);" id="bkl-fc-front-text-${bookletId}">
                      ${(typeof formatInlineMd === 'function') ? formatInlineMd(firstFc.front) : firstFc.front}
                    </div>
                  </div>
                  <div style="font-size: 11px; color: var(--text-muted); text-align: center; margin-top: 14px;">
                    👆 Toque no cartão para virar e ver a resposta
                  </div>
                </div>

                <div id="bkl-fc-back-${bookletId}" style="display: none; flex-direction: column; justify-content: space-between; height: 100%;">
                  <div>
                    <span style="display: inline-block; font-size: 10px; font-weight: 700; color: #38bdf8; background: rgba(14, 165, 233, 0.15); padding: 2px 7px; border-radius: 4px; margin-bottom: 10px;">
                      💡 RESPOSTA & RACIOCÍNIO CLÍNICO
                    </span>
                    <div style="font-size: 14px; line-height: 1.5; color: var(--text-primary);" id="bkl-fc-back-text-${bookletId}">
                      ${(typeof formatInlineMd === 'function') ? formatInlineMd(firstFc.back) : firstFc.back}
                    </div>
                  </div>
                  <div style="font-size: 11px; color: var(--text-muted); text-align: center; margin-top: 14px;">
                    👆 Toque no cartão para voltar à pergunta
                  </div>
                </div>
              </div>

              <div style="display: flex; justify-content: space-between; align-items: center; margin-top: 14px; gap: 8px;">
                <button class="btn-clean-action" onclick="navChatBookletFlashcard('${bookletId}', -1)">
                  ◀ Anterior
                </button>
                <button class="btn-clean-action" style="color: #10b981; font-weight: 600;" onclick="flipChatBookletFlashcard('${bookletId}')">
                  🔄 Virar Cartão
                </button>
                <button class="btn-clean-action" onclick="navChatBookletFlashcard('${bookletId}', 1)">
                  Próximo ▶
                </button>
              </div>
            </div>
          </div>
        </div>
      `;
    }

    /**
     * Alternador de Abas do Caderno no Chat
     */
    function selectChatBookletTab(bookletId, tabName) {
      const card = document.getElementById(`bkl-card-${bookletId}`);
      if (!card) return;
      card.querySelectorAll('.chat-booklet-tab').forEach(t => {
        t.classList.toggle('active', t.getAttribute('data-tab') === tabName);
      });
      card.querySelectorAll('.chat-booklet-pane').forEach(p => {
        p.classList.toggle('active', p.getAttribute('data-pane') === tabName);
      });
      if (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) {
        window.chatQuestionBooklets[bookletId].activeTab = tabName;
      }
    }

    /**
     * Resposta e Feedback Imediato no Quiz Interativo do Chat
     */
    function answerChatBookletQuizOption(bookletId, qId, optIdx) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet) return;
      if (typeof booklet.stats.userChoices[qId] === 'number') return;

      booklet.stats.userChoices[qId] = optIdx;
      booklet.stats.answered++;

      const q = booklet.allQuizQuestions.find(item => item.id === qId);
      if (!q) return;

      const isCorrect = (optIdx === q.correctIndex);
      if (isCorrect) {
        booklet.stats.correct++;
      }

      const optsContainer = document.getElementById(`bkl-opts-${qId}`);
      if (optsContainer) {
        optsContainer.style.pointerEvents = 'none';
        const optEls = optsContainer.querySelectorAll('.quiz-opt');
        optEls.forEach((el, idx) => {
          if (idx === q.correctIndex) {
            el.classList.add('correct');
          } else if (idx === optIdx && !isCorrect) {
            el.classList.add('incorrect');
          }
        });
      }

      const feedbackEl = document.getElementById(`bkl-feedback-${qId}`);
      if (feedbackEl) {
        feedbackEl.className = 'chat-quiz-feedback ' + (isCorrect ? 'show-correct' : 'show-wrong');
        const correctLetter = String.fromCharCode(65 + q.correctIndex);
        feedbackEl.innerHTML = `
          <div style="font-weight: 700; margin-bottom: 6px; display: flex; align-items: center; gap: 6px;">
            <span>${isCorrect ? '✅ Resposta Correta!' : '❌ Incorreto.'}</span>
            <span style="font-size: 11px; opacity: 0.85;">(Gabarito Oficial: Alternativa ${correctLetter})</span>
          </div>
          <div style="margin-bottom: 6px;">${(typeof formatInlineMd === 'function') ? formatInlineMd(q.explanation || 'Conforme diretrizes clínicas.') : (q.explanation || 'Conforme diretrizes clínicas.')}</div>
          ${q.tripartite?.pearl ? `
            <div style="margin-top: 8px; padding-top: 6px; border-top: 1px solid rgba(255, 255, 255, 0.1); font-size: 11.5px; color: #34d399;">
              💡 <strong>Pérola de Prova / ENARE:</strong> ${(typeof formatInlineMd === 'function') ? formatInlineMd(q.tripartite.pearl) : q.tripartite.pearl}
            </div>
          ` : ''}
        `;
      }

      const trackerEl = document.getElementById(`bkl-tracker-${bookletId}`);
      const scoreEl = document.getElementById(`bkl-score-${bookletId}`);
      if (scoreEl) {
        const pct = Math.round((booklet.stats.correct / booklet.stats.answered) * 100);
        scoreEl.textContent = `${booklet.stats.correct} (${pct}%)`;
      }
      if (trackerEl) {
        const progSpan = trackerEl.querySelector('span:first-child strong');
        if (progSpan) {
          progSpan.textContent = `${booklet.stats.answered}/${booklet.allQuizQuestions.length} respondidas`;
        }
      }
    }

    /**
     * Vira Flashcard Interativo no Chat
     */
    function flipChatBookletFlashcard(bookletId) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet) return;
      booklet.flashcardFlipped = !booklet.flashcardFlipped;
      const cardEl = document.getElementById(`bkl-fc-card-${bookletId}`);
      const frontEl = document.getElementById(`bkl-fc-front-${bookletId}`);
      const backEl = document.getElementById(`bkl-fc-back-${bookletId}`);
      if (cardEl && frontEl && backEl) {
        cardEl.classList.toggle('flipped', booklet.flashcardFlipped);
        frontEl.style.display = booklet.flashcardFlipped ? 'none' : 'flex';
        backEl.style.display = booklet.flashcardFlipped ? 'flex' : 'none';
      }
    }

    /**
     * Navegação entre Flashcards do Chat
     */
    function navChatBookletFlashcard(bookletId, delta) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet || !booklet.flashcards || booklet.flashcards.length === 0) return;
      const total = booklet.flashcards.length;
      booklet.currentFlashcardIndex = (booklet.currentFlashcardIndex + delta + total) % total;
      booklet.flashcardFlipped = false;

      const card = booklet.flashcards[booklet.currentFlashcardIndex];
      const cardEl = document.getElementById(`bkl-fc-card-${bookletId}`);
      const frontEl = document.getElementById(`bkl-fc-front-${bookletId}`);
      const backEl = document.getElementById(`bkl-fc-back-${bookletId}`);
      const frontTextEl = document.getElementById(`bkl-fc-front-text-${bookletId}`);
      const backTextEl = document.getElementById(`bkl-fc-back-text-${bookletId}`);
      const numEl = document.getElementById(`bkl-fc-num-${bookletId}`);

      if (numEl) numEl.textContent = (booklet.currentFlashcardIndex + 1);
      if (frontTextEl) frontTextEl.innerHTML = (typeof formatInlineMd === 'function') ? formatInlineMd(card.front) : card.front;
      if (backTextEl) backTextEl.innerHTML = (typeof formatInlineMd === 'function') ? formatInlineMd(card.back) : card.back;
      if (cardEl && frontEl && backEl) {
        cardEl.classList.remove('flipped');
        frontEl.style.display = 'flex';
        backEl.style.display = 'none';
      }
    }

    /**
     * Emissão da Apostila Completa em PDF A4 com Caixas e Linhas Pautadas para Impressão
     */
    function emitChatBookletPdf(bookletId) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      const modal = document.getElementById('readerModal');
      const content = document.getElementById('readerModalContent');
      const titleEl = document.getElementById('readerModalTitle');
      const subtitleEl = document.getElementById('readerModalSubtitle');

      if (!modal || !content) return;

      const title = booklet ? booklet.title : 'Caderno de Questões';
      const subject = booklet ? booklet.subject : (currentStudySubject || 'Medicina');
      const studentName = (typeof currentUser !== 'undefined' && currentUser?.name) ? currentUser.name : 'Estudante de Medicina';
      const currentDate = new Date().toLocaleDateString('pt-BR', { day: '2-digit', month: 'long', year: 'numeric' });

      if (titleEl) titleEl.textContent = title;
      if (subtitleEl) subtitleEl.textContent = `Caderno de Questões Impresso • ${subject} • Padrão A4`;

      const printBodyHtml = booklet ? booklet.formattedHtml : (content.innerHTML || '');

      content.innerHTML = `
        <div class="academic-report-container" style="padding: 2.5cm 2cm 2cm 2cm; max-width: 820px; margin: 0 auto; color: #111827; background: #ffffff;">
          <!-- CABEÇALHO INSTITUCIONAL -->
          <div style="text-align: center; border-bottom: 2pt solid #059669; padding-bottom: 12px; margin-bottom: 20px;">
            <div style="font-size: 10pt; font-weight: 700; letter-spacing: 1.5px; color: #059669; text-transform: uppercase;">Faculdade de Medicina • MedTutor Brasil</div>
            <div style="font-size: 8pt; color: #64748b; margin-top: 2px;">SISTEMA INTELIGENTE DE FORMAÇÃO MÉDICA E AVALIAÇÃO FORMATIVA</div>
            <h1 style="font-size: 16pt; font-weight: 800; color: #0f172a; margin: 12px 0 6px 0; text-transform: uppercase; line-height: 1.3;">${escapeHtml(title)}</h1>
            <div style="font-size: 9.5pt; color: #059669; font-weight: 700;">CADERNO DE QUESTÕES & AVALIAÇÃO FORMATIVA (NÍVEL FÁCIL AO AVANÇADO)</div>
            <div style="font-size: 9pt; color: #475569; font-weight: 600; margin-top: 3px;">Eixo Curricular: ${escapeHtml(subject)}</div>
          </div>

          <!-- TABELA DE METADADOS OFICIAIS DE PROVA -->
          <table class="abnt-header-table" style="width: 100%; border-collapse: collapse; border-top: 1.5pt solid #059669; border-bottom: 1.5pt solid #059669; margin-bottom: 22px; background: #f8fafc; font-size: 9pt;">
            <tr>
              <td style="width: 50%; padding: 8px 12px; border-right: 1pt solid #cbd5e1; vertical-align: top;">
                <div style="margin-bottom: 3px;"><strong>Acadêmico(a):</strong> ${escapeHtml(studentName)}</div>
                <div style="margin-bottom: 3px;"><strong>Tipo de Documento:</strong> Caderno de Questões para Impressão</div>
                <div><strong>Data de Emissão:</strong> ${currentDate}</div>
              </td>
              <td style="width: 50%; padding: 8px 12px; vertical-align: top;">
                <div style="margin-bottom: 3px;"><strong>Metodologia:</strong> Dificuldade Gradual (Fácil ➔ Casos Clínicos ENARE)</div>
                <div style="margin-bottom: 3px;"><strong>Estrutura:</strong> Múltipla Escolha (Papel) + Discursivas Pautadas</div>
                <div><strong>Formato:</strong> Papel A4 Normalizado (Impressão & Estudo Manual)</div>
              </td>
            </tr>
          </table>

          <!-- AVISO / INSTRUÇÕES PARA O ESTUDANTE -->
          <div style="background: #f0fdf4; border: 1pt solid #bbf7d0; border-radius: 4pt; padding: 8pt 12pt; margin-bottom: 20pt; font-size: 8.5pt; color: #166534; line-height: 1.5;">
            <strong>INSTRUÇÕES DE PREENCHIMENTO EM PAPEL:</strong><br>
            • Para as questões de múltipla escolha, assinale com caneta esferográfica a caixa <strong>☐</strong> correspondente.<br>
            • Para as questões discursivas, responda manuscrito respeitando o limite das linhas pautadas oficiais.<br>
            • O Gabarito Comentado e os Critérios de Correção constam na seção final deste caderno para autocorreção e estudo ativo.
          </div>

          <!-- CORPO DA APOSTILA COM OPÇÕES ☐ E LINHAS PAUTADAS -->
          <div class="report-body-content" style="font-size: 10.5pt; line-height: 1.6; text-align: justify;">
            ${printBodyHtml}
          </div>

          <!-- RODAPÉ FORMAL -->
          <div style="margin-top: 40px; padding-top: 14px; border-top: 1pt solid #cbd5e1; font-size: 8pt; color: #64748b; display: flex; justify-content: space-between;">
            <span>MedTutor Brasil - Caderno de Questões e Avaliação Formativa</span>
            <span>Folha de Questões • Padrão A4 Impressão</span>
          </div>
        </div>
      `;

      modal.classList.add('active');
      showToast('🖨️ Abrindo diálogo para impressão da apostila em PDF A4...');
      setTimeout(() => {
        window.print();
      }, 350);
    }

    /**
     * Modal para Salvar Caderno em uma Disciplina Específica
     */
    function openSaveBookletToSubjectModal(bookletId) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet) {
        showToast('⚠️ Caderno de questões não encontrado.');
        return;
      }
      activeSavingBookletId = bookletId;

      const select = document.getElementById('saveBookletSubjectSelect');
      const customGroup = document.getElementById('saveBookletCustomSubjectGroup');
      const customInput = document.getElementById('saveBookletCustomSubjectInput');
      const summaryBox = document.getElementById('saveBookletSummaryBox');
      const modal = document.getElementById('saveBookletModal');

      if (!modal || !select) return;

      if (customGroup) customGroup.style.display = 'none';
      if (customInput) customInput.value = '';

      const allSubjs = typeof getAllCurriculumSubjects === 'function' ? getAllCurriculumSubjects() : [];
      const uniqueNames = Array.from(new Set(allSubjs.map(s => s.name || s).filter(Boolean)));
      
      const currentSubj = booklet.subject || currentStudySubject || (uniqueNames[0] || 'Clínica Médica');
      if (!uniqueNames.includes(currentSubj)) {
        uniqueNames.unshift(currentSubj);
      }

      select.innerHTML = uniqueNames.map(name => `
        <option value="${escapeHtml(name)}" ${name === currentSubj ? 'selected' : ''}>
          ${escapeHtml(name)}
        </option>
      `).join('') + `
        <option value="__new__">+ Criar Nova Disciplina...</option>
      `;

      if (summaryBox) {
        const qCount = booklet.allQuizQuestions ? booklet.allQuizQuestions.length : 0;
        const fcCount = booklet.flashcards ? booklet.flashcards.length : 0;
        summaryBox.innerHTML = `
          <strong>Itens do Caderno a serem indexados:</strong><br>
          • <strong>${qCount} questões</strong> de múltipla escolha (Fáceis, Intermediárias e Casos Clínicos)<br>
          • <strong>${fcCount} flashcards</strong> de memorização e fixação ativa<br>
          <span style="font-size: 11px; color: var(--text-muted); display: block; margin-top: 4px;">
            Origem: Chat do MedTutor AI • Ficarão acessíveis nas abas Quizzes e Flashcards desta matéria.
          </span>
        `;
      }

      modal.classList.add('active');
    }

    function onBookletSubjectSelectChange(val) {
      const customGroup = document.getElementById('saveBookletCustomSubjectGroup');
      if (customGroup) {
        customGroup.style.display = (val === '__new__') ? 'block' : 'none';
        if (val === '__new__') {
          const customInput = document.getElementById('saveBookletCustomSubjectInput');
          if (customInput) customInput.focus();
        }
      }
    }

    function confirmSaveBookletToSubject() {
      const bookletId = activeSavingBookletId;
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet) {
        showToast('⚠️ Erro ao localizar apostila.');
        return;
      }

      const select = document.getElementById('saveBookletSubjectSelect');
      const customInput = document.getElementById('saveBookletCustomSubjectInput');
      let targetSubject = select ? select.value : '';

      if (targetSubject === '__new__') {
        targetSubject = customInput ? customInput.value.trim() : '';
        if (!targetSubject) {
          showToast('⚠️ Digite o nome da nova disciplina.');
          return;
        }
      }

      if (!targetSubject) targetSubject = 'Clínica Médica';

      let addedQuestionsCount = 0;
      let addedFlashcardsCount = 0;

      // 1. Converte e salva questões de múltipla escolha no sharedQuestionsBank
      if (Array.isArray(booklet.allQuizQuestions)) {
        booklet.allQuizQuestions.forEach((q, idx) => {
          const qObj = {
            id: 'chat-q-' + Date.now() + '-' + idx,
            subject: targetSubject,
            disease: booklet.title,
            topic: booklet.title,
            vignette: q.vignette || '',
            question: q.question,
            quizOptions: q.options || [],
            correctIndex: typeof q.correctIndex === 'number' ? q.correctIndex : 0,
            explanation: q.explanation || '',
            tripartite: {
              correctReason: q.explanation || '',
              distractorAnalysis: q.distractorAnalysis || {},
              pearl: q.tripartite?.pearl || q.pearl || ''
            },
            reference_answer: q.reference_answer || q.explanation || '',
            answer: q.reference_answer || q.explanation || '',
            flashcard: {
              front: q.question,
              back: q.reference_answer || q.explanation || '',
              keyConcepts: [targetSubject.toLowerCase(), 'chat', 'apostila']
            },
            difficultyLevel: q.level === 'fácil' ? 'iniciante' : (q.level === 'intermediário' ? 'intermediario' : 'avancado'),
            cognitiveDomain: q.level === 'fácil' ? 'conceitual' : (q.level === 'intermediário' ? 'mecanismo' : 'aplicacao'),
            sourceOrigin: 'Apostila do Chat',
            isStarred: false,
            createdAt: new Date().toISOString()
          };
          sharedQuestionsBank.unshift(qObj);
          addedQuestionsCount++;
        });
      }

      // 2. Converte e salva flashcards no sharedQuestionsBank
      if (Array.isArray(booklet.flashcards)) {
        booklet.flashcards.forEach((fc, idx) => {
          const fcObj = {
            id: 'chat-fc-' + Date.now() + '-' + idx,
            subject: targetSubject,
            disease: booklet.title,
            topic: booklet.title,
            question: fc.front,
            quizOptions: [],
            correctIndex: 0,
            explanation: fc.back,
            reference_answer: fc.back,
            answer: fc.back,
            flashcard: {
              front: fc.front,
              back: fc.back,
              keyConcepts: [targetSubject.toLowerCase(), 'chat', 'flashcard']
            },
            difficultyLevel: 'iniciante',
            cognitiveDomain: 'conceitual',
            sourceOrigin: 'Apostila do Chat (Flashcard)',
            isStarred: false,
            createdAt: new Date().toISOString()
          };
          sharedQuestionsBank.unshift(fcObj);
          addedFlashcardsCount++;
        });
      }

      booklet.savedToSubject = true;
      booklet.savedSubjectName = targetSubject;

      const saveBtn = document.getElementById(`bkl-btn-save-${bookletId}`);
      if (saveBtn) {
        saveBtn.innerHTML = `✅ Salvo em: ${escapeHtml(targetSubject)}`;
        saveBtn.style.background = 'rgba(16, 185, 129, 0.15)';
        saveBtn.style.color = '#34d399';
        saveBtn.style.borderColor = 'rgba(16, 185, 129, 0.35)';
      }

      if (typeof renderSharedStudyItems === 'function') renderSharedStudyItems();
      if (typeof renderSceBars === 'function') renderSceBars();
      if (typeof updateSubjectFilterMenus === 'function') updateSubjectFilterMenus();

      const modal = document.getElementById('saveBookletModal');
      if (modal) modal.classList.remove('active');

      showToast(`✅ ${addedQuestionsCount} questões e ${addedFlashcardsCount} flashcards salvos na matéria "${targetSubject}"!`);
    }

    function copyChatBookletText(bookletId) {
      const booklet = (window.chatQuestionBooklets && window.chatQuestionBooklets[bookletId]) || null;
      if (!booklet || !booklet.rawText) {
        showToast('⚠️ Conteúdo não encontrado para cópia.');
        return;
      }
      navigator.clipboard.writeText(booklet.rawText);
      showToast('📋 Apostila copiada para a área de transferência!');
    }

    // =========================================================================
    // IMPORTAÇÃO INTELIGENTE DE MATERIAIS / APOSTILAS EM FLASHCARDS & QUIZZES
    // COM RECONHECIMENTO DE QUESTÕES / TEXTO / AMBOS E CHECKBOX DE MATERIAIS
    // =========================================================================
    let pendingImportStudySource = 'flashcards';
    let pendingImportStudyFile = null;

    /**
     * Abre o modal de upload inteligente contextualizado para Flashcards ou Quizzes
     */
    function openImportStudyMaterialModal(sourceSection) {
      pendingImportStudySource = sourceSection || 'flashcards';
      pendingImportStudyFile = null;

      const titleEl = document.getElementById('importStudyModalTitle');
      const subEl = document.getElementById('importStudySourceSubtitle');
      if (titleEl) {
        titleEl.textContent = sourceSection === 'quizzes' 
          ? 'Upload de Material para Quizzes & Flashcards' 
          : 'Upload de Material para Flashcards & Quizzes';
      }
      if (subEl) {
        subEl.textContent = sourceSection === 'quizzes'
          ? '⚡ Seção Ativa: Quizzes • Reconhecimento Inteligente por IA'
          : '🗂️ Seção Ativa: Flashcards • Reconhecimento Inteligente por IA';
      }

      // Popula o seletor de disciplinas
      const select = document.getElementById('importStudySubjectSelect');
      const customGroup = document.getElementById('importStudyCustomSubjectGroup');
      const customInput = document.getElementById('importStudyCustomSubjectInput');
      if (customGroup) customGroup.style.display = 'none';
      if (customInput) customInput.value = '';

      if (select) {
        const allSubjs = typeof getAllCurriculumSubjects === 'function' ? getAllCurriculumSubjects() : [];
        const uniqueNames = Array.from(new Set(allSubjs.map(s => s.name || s).filter(Boolean)));
        const activeSubj = currentStudySubject || (uniqueNames[0] || 'Clínica Médica');
        if (!uniqueNames.includes(activeSubj)) {
          uniqueNames.unshift(activeSubj);
        }

        select.innerHTML = uniqueNames.map(name => `
          <option value="${escapeHtml(name)}" ${name === activeSubj ? 'selected' : ''}>
            ${escapeHtml(name)}
          </option>
        `).join('') + `
          <option value="__new__">➕ Criar Nova Disciplina...</option>
        `;
      }

      // Reseta abas de entrada (Arquivo vs Texto)
      switchImportStudyTab('file');

      // Reseta campo de arquivo e dropzone
      const fileInput = document.getElementById('importStudyFileInput');
      if (fileInput) fileInput.value = '';
      const zoneTitle = document.getElementById('importStudyDropZoneTitle');
      const zoneSub = document.getElementById('importStudyDropZoneSub');
      if (zoneTitle) zoneTitle.textContent = 'Arraste ou clique para selecionar apostila, prova ou resumo';
      if (zoneSub) zoneSub.textContent = 'Suporta PDF, DOCX, TXT ou Markdown • Reconhecimento de perguntas e texto';

      // Reseta campo de texto
      const textInput = document.getElementById('importStudyTextInput');
      if (textInput) textInput.value = '';

      // Reseta checkbox de salvar em materiais (PADRÃO: DESMARCADO, conforme solicitado pelo usuário)
      const saveAsMatCheckbox = document.getElementById('importStudySaveAsMaterialCheckbox');
      if (saveAsMatCheckbox) saveAsMatCheckbox.checked = false;
      const visualAssociationCheckbox = document.getElementById('importStudyVisualAssociationCheckbox');
      if (visualAssociationCheckbox) visualAssociationCheckbox.checked = false;

      // Reseta progresso e botão
      const progressBox = document.getElementById('importStudyProgressBox');
      if (progressBox) progressBox.style.display = 'none';
      const btnConfirm = document.getElementById('btnConfirmImportStudy');
      if (btnConfirm) {
        btnConfirm.disabled = false;
        btnConfirm.textContent = '✨ Processar com IA';
      }

      const modal = document.getElementById('modalImportStudyMaterial');
      if (modal) modal.classList.add('active');
    }

    function onImportStudySubjectChange(val) {
      const customGroup = document.getElementById('importStudyCustomSubjectGroup');
      if (customGroup) {
        customGroup.style.display = (val === '__new__') ? 'block' : 'none';
        if (val === '__new__') {
          const input = document.getElementById('importStudyCustomSubjectInput');
          if (input) input.focus();
        }
      }
    }

    function switchImportStudyTab(tab) {
      const btnFile = document.getElementById('btnImportTabFile');
      const btnText = document.getElementById('btnImportTabText');
      const panelFile = document.getElementById('importStudyPanelFile');
      const panelText = document.getElementById('importStudyPanelText');

      if (btnFile && btnText && panelFile && panelText) {
        if (tab === 'file') {
          btnFile.classList.add('active');
          btnText.classList.remove('active');
          panelFile.style.display = 'block';
          panelText.style.display = 'none';
        } else {
          btnFile.classList.remove('active');
          btnText.classList.add('active');
          panelFile.style.display = 'none';
          panelText.style.display = 'block';
          const textInput = document.getElementById('importStudyTextInput');
          if (textInput) textInput.focus();
        }
      }
    }

    function handleImportStudyFileSelected(input) {
      const file = input && input.files && input.files[0];
      if (!file) return;

      pendingImportStudyFile = file;
      const zoneTitle = document.getElementById('importStudyDropZoneTitle');
      const zoneSub = document.getElementById('importStudyDropZoneSub');
      const sizeMB = (file.size / (1024 * 1024)).toFixed(2);

      if (zoneTitle) zoneTitle.textContent = `✅ Arquivo Selecionado: ${file.name}`;
      if (zoneSub) zoneSub.textContent = `${sizeMB} MB • Pronto para extração de texto e análise por IA`;
      showToast(`📄 Arquivo "${file.name}" carregado. Clique em "Processar com IA".`);
    }

    /**
     * Processamento mestre do material com IA
     */
    async function processImportStudyMaterial() {
      const select = document.getElementById('importStudySubjectSelect');
      const customInput = document.getElementById('importStudyCustomSubjectInput');
      let targetSubject = select ? select.value : '';

      if (targetSubject === '__new__') {
        targetSubject = customInput ? customInput.value.trim() : '';
        if (!targetSubject) {
          showToast('⚠️ Por favor, digite o nome da nova disciplina.');
          if (customInput) customInput.focus();
          return;
        }
      }
      if (!targetSubject) targetSubject = currentStudySubject || 'Medicina';

      const isTextTab = document.getElementById('importStudyPanelText')?.style.display !== 'none';
      const textInput = document.getElementById('importStudyTextInput');
      const pastedText = textInput ? textInput.value.trim() : '';

      if (isTextTab && !pastedText) {
        showToast('⚠️ Digite ou cole o texto do material.');
        if (textInput) textInput.focus();
        return;
      }
      if (!isTextTab && !pendingImportStudyFile) {
        showToast('⚠️ Selecione um arquivo (PDF, DOCX, TXT) ou cole o texto.');
        return;
      }

      const saveAsMaterial = document.getElementById('importStudySaveAsMaterialCheckbox')?.checked || false;
      const generateIndividualReport = document.getElementById('importStudyGenerateReportCheckbox')?.checked || false;
      const visualAssociationEnabled = document.getElementById('importStudyVisualAssociationCheckbox')?.checked || false;

      // Inicia exibição de progresso
      const progressBox = document.getElementById('importStudyProgressBox');
      const progStatus = document.getElementById('importStudyProgressStatus');
      const progBar = document.getElementById('importStudyProgressBar');
      const progDetail = document.getElementById('importStudyProgressDetail');
      const btnConfirm = document.getElementById('btnConfirmImportStudy');

      if (progressBox) progressBox.style.display = 'block';
      if (btnConfirm) {
        btnConfirm.disabled = true;
        btnConfirm.textContent = '⏳ Processando com IA...';
      }

      if (progStatus) progStatus.textContent = '1. Extraindo texto do material...';
      if (progBar) progBar.style.width = '25%';
      if (progDetail) progDetail.textContent = isTextTab ? 'Lendo texto fornecido...' : `Lendo ${pendingImportStudyFile.name} com PDF.js e parsers nativos...`;

      let extractedText = '';
      let fileName = 'Material Importado';

      try {
        if (isTextTab) {
          extractedText = pastedText;
          fileName = 'Texto Didático • ' + targetSubject;
        } else {
          fileName = pendingImportStudyFile.name;
          extractedText = await extractTextFromFile(pendingImportStudyFile);
        }
      } catch (err) {
        console.error('Erro na extração de texto:', err);
      }

      let visualAssociations = [];
      const isVisualFile = !isTextTab && /(?:\.pdf|\.pptx?)$/i.test(fileName);
      if (visualAssociationEnabled && isVisualFile && pendingImportStudyFile) {
        if (progStatus) progStatus.textContent = '2. Interpretando páginas e marcos visuais com Gemini...';
        if (progBar) progBar.style.width = '55%';
        if (progDetail) progDetail.textContent = 'Enviando somente as imagens do PDF/slide autorizadas nesta importação...';
        visualAssociations = await analyzeVisualMaterialAssociations(pendingImportStudyFile, { fileName, targetSubject });
      }

      if ((!extractedText || extractedText.trim().length < 20) && !visualAssociations.length) {
        showToast('⚠️ Não foi possível extrair texto suficiente deste arquivo. Tente colar o texto diretamente.');
        if (progressBox) progressBox.style.display = 'none';
        if (btnConfirm) {
          btnConfirm.disabled = false;
          btnConfirm.textContent = '✨ Processar com IA';
        }
        return;
      }

      if (progStatus) progStatus.textContent = '2. Analisando perguntas e texto com IA...';
      if (progBar) progBar.style.width = '60%';
      if (progDetail) progDetail.textContent = 'Identificando se são questões existentes, teoria ou misto...';

      // Executa análise e transformação por IA (Gemini ou Heurística Local)
      const visualMarkdown = visualAssociations.length
        ? `# Associação Visual do Material\n\n${visualAssociations.map((item, index) => `## Figura ${index + 1}: ${item.title}\n\n**Estruturas/marcos visíveis:** ${(item.visibleStructures || []).join(', ') || 'Não identificados com segurança.'}\n\n${item.association}\n\n${item.caution ? `> Atenção: ${item.caution}\n\n` : ''}**Recuperação ativa:** ${item.studyQuestion || 'Quais estruturas e relações podem ser reconhecidas nesta figura?'}\n`).join('\n')}`
        : '';
      let analysisResult;
      if (extractedText && extractedText.trim().length >= 20) {
        analysisResult = await analyzeAndTransformStudyMaterial(extractedText, {
          fileName: fileName,
          targetSubject: targetSubject,
          saveAsMaterial: saveAsMaterial
        });
      } else {
        extractedText = visualMarkdown;
        analysisResult = { detectedType: 'visual_only', clinicalSubject: targetSubject, items: [], reusedQuestionsCount: 0, generatedFromTextCount: 0 };
      }

      if (progStatus) progStatus.textContent = '3. Integrando questões e flashcards...';
      if (progBar) progBar.style.width = '90%';
      if (progDetail) progDetail.textContent = 'Indexando no banco de estudos...';

      // 4. Trata o salvamento ou não na seção de Materiais do Aluno
      let importedStudyMaterial = null;
      if (saveAsMaterial || generateIndividualReport || visualAssociationEnabled) {
        // Aluno optou por salvar na biblioteca de materiais
        const newMaterial = {
          id: 'mat-' + Date.now() + '-' + Math.random().toString(36).substr(2, 6),
          name: fileName,
          originalFileName: fileName,
          title: fileName.replace(/\.[^/.]+$/, ''),
          subject: targetSubject,
          disease: targetSubject,
          topic: fileName.replace(/\.[^/.]+$/, ''),
          tag: 'Apostila / Material Importado',
          sizeStr: pendingImportStudyFile ? `${(pendingImportStudyFile.size / (1024 * 1024)).toFixed(1)} MB` : `${(extractedText.length / 1024).toFixed(1)} KB`,
          selected: true,
          readingDocText: `${extractedText}${visualMarkdown && !extractedText.includes('Associação Visual do Material') ? `\n\n${visualMarkdown}` : ''}`,
          readingDocHtml: (typeof formatAITextToHTML === 'function') ? formatAITextToHTML(extractedText) : `<pre>${escapeHtml(extractedText)}</pre>`,
          text: `${extractedText}${visualMarkdown && !extractedText.includes('Associação Visual do Material') ? `\n\n${visualMarkdown}` : ''}`,
          markdownText: `${extractedText}${visualMarkdown && !extractedText.includes('Associação Visual do Material') ? `\n\n${visualMarkdown}` : ''}`,
          visualAssociations,
          visualAssociationAuthorized: visualAssociationEnabled,
          // Preserva métricas da importação para o diagnóstico operacional no terminal.
          // O conteúdo do arquivo nunca é enviado para esse diagnóstico.
          uploadInputChars: String(extractedText || '').length,
          aiEngine: visualAssociationEnabled
            ? 'Gemini via servidor local (associação visual)'
            : (analysisResult.engine || 'Motor local (fallback)'),
          createdAt: new Date().toISOString()
        };

        if (Array.isArray(chatDriveMaterials)) {
          chatDriveMaterials.unshift(newMaterial);
          if (typeof sortChatDriveMaterialsInLearningOrder === 'function') {
            sortChatDriveMaterialsInLearningOrder();
          }
          saveChatDriveMaterials();
          if (pendingImportStudyFile) {
            reportUploadDiagnostic(newMaterial, 'iniciando');
            attachOriginalDocumentImages(newMaterial, pendingImportStudyFile, visualAssociations)
              .then(() => reportUploadDiagnostic(newMaterial, 'sucesso'))
              .catch(error => {
                console.warn('[Imagens do material] Falha ao anexar imagens da importação:', error);
                reportUploadDiagnostic(newMaterial, 'parcial');
              });
          } else {
            reportUploadDiagnostic(newMaterial, 'sucesso');
          }
        }
        importedStudyMaterial = newMaterial;
      } else {
        // Aluno optou por NÃO salvar na biblioteca de materiais:
        // Mantém chatDriveMaterials intocado!
        console.log(`[Importação] Arquivo "${fileName}" processado estritamente para Quiz/Flashcards sem persistir na lista de materiais do aluno.`);
        reportUploadDiagnostic({
          originalFileName: fileName,
          uploadInputChars: String(extractedText || '').length,
          markdownText: `${extractedText || ''}${visualMarkdown || ''}`,
          visualAssociationAuthorized: visualAssociationEnabled,
          aiEngine: visualAssociationEnabled
            ? 'Gemini via servidor local (associação visual)'
            : (analysisResult.engine || 'Motor local (fallback)'),
          clinicalImages: visualAssociations
        }, 'sucesso');
      }

      // 5. Salva todas as questões e flashcards no sharedQuestionsBank
      const items = (analysisResult.items || []).map(item => ({
        ...item,
        question: sanitizeSharedQuestionStem(item.question || item.flashcardFront || '')
      })).filter(item => isSharedQuestionStemValid(item.question));
      let cleanFileTitle = fileName.replace(/\.[^/.]+$/, '').trim();
      cleanFileTitle = cleanFileTitle.replace(/\b(gabarito|e\.?d\.?|estudo\s*dirigido|simulado|prova|caderno|apostila|quest[oõ]es|aula|slide|modulo|capitulo)\s*\d*\b/gi, '').trim();
      cleanFileTitle = cleanFileTitle.replace(/^[_\-\s\.\:]+|[_\-\s\.\:]+$/g, '').trim();
      if (!cleanFileTitle || cleanFileTitle.length < 3) cleanFileTitle = targetSubject || 'Medicina';

      const resolvedClinicalTopic = analysisResult.clinicalSubject || cleanFileTitle;

      const newQuestionObjects = items.map((item, idx) => {
        const isReused = item.source === 'reused';
        const qId = 'import-q-' + Date.now() + '-' + idx;
        const correctIdx = (typeof item.correctIndex === 'number' && item.correctIndex >= 0 && item.correctIndex < (item.options?.length || 4)) 
          ? item.correctIndex 
          : 0;

        return {
          id: qId,
          subject: targetSubject,
          disease: resolvedClinicalTopic,
          topic: resolvedClinicalTopic,
          slideName: fileName,
          vignette: item.vignette || '',
          question: item.question,
          quizOptions: Array.isArray(item.options) && item.options.length >= 2 
            ? item.options 
            : ['Opção A', 'Opção B', 'Opção C', 'Opção D'],
          correctIndex: correctIdx,
          explanation: item.explanation || 'Conforme diretrizes clínicas e material didático.',
          tripartite: {
            correctReason: item.explanation || '',
            distractorAnalysis: item.distractorAnalysis || {},
            pearl: item.pearl || ''
          },
          reference_answer: item.explanation || '',
          answer: item.explanation || '',
          flashcard: {
            front: item.question,
            back: item.flashcardBack || item.explanation || '',
            keyConcepts: [targetSubject.toLowerCase(), isReused ? 'reaproveitada' : 'gerada_ia']
          },
          difficultyLevel: item.difficulty || 'intermediario',
          cognitiveDomain: item.difficulty === 'iniciante' ? 'conceitual' : (item.difficulty === 'avancado' ? 'aplicacao' : 'mecanismo'),
          sourceOrigin: isReused ? 'Apostila (Questão Reaproveitada)' : 'Material Didático (Gerada por IA)',
          isReused: isReused,
          isStarred: false,
          createdAt: new Date().toISOString()
        };
      });

      // Adiciona as questões ao topo do banco geral
      newQuestionObjects.reverse().forEach(q => sharedQuestionsBank.unshift(q));
      saveSharedQuestionsBank();

      // Atualiza o estado da disciplina
      if (!subjectGenerationStatus[targetSubject]) {
        subjectGenerationStatus[targetSubject] = { status: 'ready', materialsCount: 1, questionsCount: 0 };
      }
      subjectGenerationStatus[targetSubject].status = 'ready';
      subjectGenerationStatus[targetSubject].questionsCount = sharedQuestionsBank.filter(q => q.subject === targetSubject).length;

      currentStudySubject = targetSubject;
      currentQuizSlideFilter = 'all';

      // Atualiza a interface
      renderSharedStudyItems();
      renderSlideSelectors();
      renderQuizzesList();
      if (typeof renderCurriculumGrid === 'function') renderCurriculumGrid();
      if (typeof renderSceBars === 'function') renderSceBars();
      if (typeof updateSubjectFilterMenus === 'function') updateSubjectFilterMenus();

      closeModals();

      // Navega e foca na aba correta
      if (pendingImportStudySource === 'quizzes') {
        navigateTab('quizzes');
      } else {
        navigateTab('flashcards');
        currentCardIndex = 0;
        updateCardDisplay();
      }

      // Feedback rico ao estudante
      const reusedCount = analysisResult.reusedQuestionsCount || 0;
      const genCount = analysisResult.generatedFromTextCount || 0;
      let typeDesc = 'Material Processado';
      if (analysisResult.detectedType === 'questions_only') {
        typeDesc = '📋 Banco de Questões (Apenas Perguntas)';
      } else if (analysisResult.detectedType === 'text_only') {
        typeDesc = '📖 Material Didático Teórico';
      } else {
        typeDesc = '⚡ Material Misto (Teoria + Questões)';
      }

      const matStatusMsg = (saveAsMaterial || generateIndividualReport || visualAssociationEnabled)
        ? 'Arquivo salvo na biblioteca de materiais.' 
        : 'Arquivo NÃO adicionado à biblioteca de materiais (estudo direto).';

      showToast(`🎉 ${typeDesc}: ${reusedCount} reaproveitadas + ${genCount} formuladas por IA! ${matStatusMsg}`);

      if (generateIndividualReport && importedStudyMaterial) {
        await openAcademicReportForMaterial(importedStudyMaterial.id, targetSubject, importedStudyMaterial.name);
      }
    }

    /**
     * Motor de Análise e Transformação: detecta perguntas, texto ou ambos
     */
    async function analyzeAndTransformStudyMaterial(text, metadata) {
      const fileName = metadata.fileName || 'Material';
      const targetSubject = metadata.targetSubject || 'Medicina';

      // 1. Tenta prioritariamente via Backend API (port 3001 com Gemini SDK oficial)
      try {
        console.log(`➡️ [Importador IA] Enviando "${fileName}" para análise no backend...`);
        const response = await fetch('/api/quizzes/analisar-material', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            text: text,
            fileName: fileName,
            targetSubject: targetSubject
          })
        });

        if (response.ok) {
          const apiResult = await response.json();
          if (apiResult && Array.isArray(apiResult.items) && apiResult.items.length > 0) {
            apiResult.engine = apiResult.model || 'Gemini via servidor local';
            console.log(`✅ [Importador IA] Análise concluída com sucesso pelo backend Gemini (${apiResult.items.length} itens).`);
            return apiResult;
          }
        } else {
          console.warn('[Importador IA] Backend respondeu status', response.status);
        }
      } catch (backendErr) {
        console.warn('[Importador IA] Backend indisponível ou inacessível, testando alternativas:', backendErr);
      }

      // 2. Fallback direto do navegador para o Gemini (caso o usuário tenha chave própria em localStorage)
      const apiKey = getGeminiApiKey();
      const cleanSample = text.slice(0, 20000);

      if (apiKey && cleanSample.length > 50) {
        try {
          const geminiResult = await analyzeAndTransformStudyMaterialWithGemini(cleanSample, metadata, apiKey);
          if (geminiResult && Array.isArray(geminiResult.items) && geminiResult.items.length > 0) {
            geminiResult.engine = 'Gemini API direta';
            return geminiResult;
          }
        } catch (geminiErr) {
          console.warn('[Importador IA] Falha no Gemini API cliente, acionando analisador heurístico local:', geminiErr);
        }
      }

      // 3. Fallback Heurístico Local Pericial Aperfeiçoado
      const localResult = analyzeAndTransformStudyMaterialLocal(text, metadata);
      localResult.engine = 'Motor local (fallback)';
      return localResult;
    }

    /**
     * Chamada estruturada ao Gemini para classificar e transformar o material
     */
    async function analyzeAndTransformStudyMaterialWithGemini(textSample, metadata, apiKey) {
      const targetSubj = metadata.targetSubject || 'Medicina';
      const fileName = metadata.fileName || 'Material';

      const promptText = `Você é um docente e examinador pericial de Residência Médica (ENARE / Revalida).
Analise rigorosamente o material biomédico fornecido a seguir:
Disciplina: "${targetSubj}" • Arquivo: "${fileName}"

DIRETRIZES OBRIGATÓRIAS:
1. RECONHECIMENTO AUTOMÁTICO DO TIPO DE CONTEÚDO:
   - "questions_only": o material contém questões de prova ou estudo dirigido com perguntas e respostas/gabarito (ex: "1) Em qual espaço...? Resposta: ..."), mesmo sem alternativas A/B/C/D prévias.
   - "text_only": o material é composto exclusivamente por texto explicativo, teoria, conceitos, slides, resumo ou anotações (sem questões).
   - "both": o material contém ambos (seções teóricas conceituais E seções de exercícios/questões).

2. PROCESSAMENTO:
   - SE HOUVER PERGUNTAS EXISTENTES ("questions_only" ou "both"):
     REAPROVEITE-AS integralmente. Extraia os enunciados, vinhetas clínicas e respostas. Formule exatamente 4 alternativas (sendo a correta fiel ao gabarito e 3 distratores médicos). Elabore justificativa e crie um par de Flashcard com pergunta e resposta para cada questão reaproveitada. Defina "source": "reused".
   - SE HOUVER TEXTO DIDÁTICO ("text_only" ou "both"):
     TRANSFORME o texto em questões clínicas inéditas no padrão ENARE/Residência, com 4 alternativas, gabarito justificado e par de Flashcard correspondente. Defina "source": "generated_from_text".
   - NUNCA use termos de cabeçalho ou arquivos (GABARITO, E.D.) como nome de patologia.
   - O campo "question" e "flashcardFront" devem ser a mesma pergunta aberta, autocontida e respondível sem alternativas. Não use “assinale a alternativa”, “marque a opção”, “de acordo com as opções” nem coloque opções no enunciado.

CONTEÚDO DO MATERIAL:
"""
${textSample}
"""
`;

      const payload = {
        contents: [{ parts: [{ text: promptText }] }],
        generationConfig: {
          temperature: 0.15,
          responseMimeType: "application/json",
          responseSchema: {
            type: "OBJECT",
            properties: {
              detectedType: { type: "STRING", enum: ["questions_only", "text_only", "both"] },
              detectedTypeDescription: { type: "STRING" },
              clinicalSubject: { type: "STRING" },
              reusedQuestionsCount: { type: "INTEGER" },
              generatedFromTextCount: { type: "INTEGER" },
              items: {
                type: "ARRAY",
                items: {
                  type: "OBJECT",
                  properties: {
                    source: { type: "STRING", enum: ["reused", "generated_from_text"] },
                    question: { type: "STRING" },
                    vignette: { type: "STRING" },
                    options: { type: "ARRAY", items: { type: "STRING" } },
                    correctIndex: { type: "INTEGER" },
                    explanation: { type: "STRING" },
                    pearl: { type: "STRING" },
                    flashcardFront: { type: "STRING" },
                    flashcardBack: { type: "STRING" },
                    difficulty: { type: "STRING", enum: ["iniciante", "intermediario", "avancado"] }
                  },
                  required: ["source", "question", "options", "correctIndex", "explanation", "flashcardFront", "flashcardBack"]
                }
              }
            },
            required: ["detectedType", "items"]
          }
        }
      };

      const models = ['gemini-2.0-flash', 'gemini-1.5-flash', 'gemini-2.5-flash'];
      for (const model of models) {
        try {
          const url = `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${encodeURIComponent(apiKey.trim())}`;
          const res = await fetch(url, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          if (!res.ok) continue;

          const data = await res.json();
          const contentStr = data.candidates?.[0]?.content?.parts?.[0]?.text;
          if (!contentStr) continue;

          const parsed = JSON.parse(contentStr);
          if (parsed && Array.isArray(parsed.items) && parsed.items.length > 0) {
            let reused = 0;
            let gen = 0;
            parsed.items.forEach(it => {
              if (it.source === 'reused') reused++;
              else gen++;
            });
            parsed.reusedQuestionsCount = reused;
            parsed.generatedFromTextCount = gen;
            return parsed;
          }
        } catch (e) {
          console.warn(`Tentativa com ${model} falhou:`, e);
        }
      }
      return null;
    }

    /**
     * Auxiliar Heurístico para gerar distratores médicos em questões discursivas importadas
     */
    function generateMedicalDistractorsForLocal(prompt, answer, topic) {
      const pLow = ((prompt || '') + ' ' + (answer || '')).toLowerCase();
      if (pLow.includes('espaço') || pLow.includes('subaracnoid') || pLow.includes('subaracnóid') || pLow.includes('meninge') || pLow.includes('líquor') || pLow.includes('liquor')) {
        return [
          'No espaço epidural craniano, delimitado entre a tábua óssea e o folheto externo da dura-máter.',
          'No espaço subdural espinhal, contido entre a dura-máter e a aracnoide.',
          'Exclusivamente no interior do espaço intraventricular sem comunicação cisternal.'
        ];
      }
      if (pLow.includes('aneurisma') || pLow.includes('vascular') || pLow.includes('willis') || pLow.includes('sangramento')) {
        return [
          'Trombose venosa do seio sagital superior com infarto hemorrágico venoso.',
          'Ruptura de malformação arteriovenosa dural com hematoma intraparenquimatoso isolado.',
          'Dissecção espontânea da artéria carótida interna cervical sem extravasamento liquórico.'
        ];
      }
      if (pLow.includes('granulaç') || pLow.includes('absorç') || pLow.includes('circulaç') || pLow.includes('hidrocefalia')) {
        return [
          'Estenose congênita não comunicante no nível do forame de Magendie e Luschka.',
          'Produção excessiva e descontrolada de líquor pelos plexos coróideos sem alteração de drenagem.',
          'Aumento da permeabilidade da barreira hematoencefálica com edema vasogênico difuso.'
        ];
      }
      return [
        `Intervenção cirúrgica imediata sem necessidade de estratificação clínica prévia em ${topic}.`,
        `Suspensão de todo o suporte intensivo e conduta estritamente expectante.`,
        `Administração isolada de antimicrobianos sem correlação com critérios de gravidade.`
      ];
    }

    /**
     * Analisador Heurístico Local (offline / fallback)
     */
    function analyzeAndTransformStudyMaterialLocal(text, metadata) {
      const cleanText = text || '';
      const targetSubj = metadata.targetSubject || 'Medicina';
      const fileName = metadata.fileName || 'Apostila';
      let cleanTitle = fileName.replace(/\.[^/.]+$/, '').trim();
      cleanTitle = cleanTitle.replace(/\b(gabarito|e\.?d\.?|estudo\s*dirigido|simulado|prova|caderno|apostila|quest[oõ]es|aula|slide|modulo|capitulo)\s*\d*\b/gi, '').trim();
      cleanTitle = cleanTitle.replace(/^[_\-\s\.\:]+|[_\-\s\.\:]+$/g, '').trim();
      if (!cleanTitle || cleanTitle.length < 3) cleanTitle = targetSubj || 'Medicina';

      // Extrai vinheta clínica presente no material (ex: "CASO CLÍNICO: Sebastião, 58 anos...")
      let detectedDocVignette = '';
      const vMatch = cleanText.match(/(?:CASO\s*CL[ÍI]NICO|HIST[ÓO]RIA\s*CL[ÍI]NICA|CEN[ÁA]RIO\s*CL[ÍI]NICO)[:\s\-–]*([^\n\r]+(?:\n(?!(?:QUEST[ÕO]ES|PERGUNTAS|\d+[\.\)]|#))([^\n\r]+))*)/i);
      if (vMatch && vMatch[0]) {
        detectedDocVignette = vMatch[0].replace(/^(?:CASO\s*CL[ÍI]NICO|HIST[ÓO]RIA\s*CL[ÍI]NICA|CEN[ÁA]RIO\s*CL[ÍI]NICO)[:\s\-–]*/i, '').trim();
        if (detectedDocVignette.length > 500) detectedDocVignette = detectedDocVignette.substring(0, 500) + '...';
      }

      // 1. Extração do Gabarito prévio (se existir em formato clássico Q1: A, Q2: B)
      const gabaritoMap = {};
      const gabaritoRegex = /(?:Quest[aã]o|Questao|\bQ\b)\s*(\d+)[:\s\-–]*(?:Alternativa|Resposta|Letra)?\s*\*?\*?([A-E])\*?\*?([^\n]*)/gi;
      let gMatch;
      while ((gMatch = gabaritoRegex.exec(cleanText)) !== null) {
        const qNum = parseInt(gMatch[1], 10);
        const letter = gMatch[2].toUpperCase();
        gabaritoMap[qNum] = letter.charCodeAt(0) - 65;
      }

      // 2. Busca por blocos de questões com opções de múltipla escolha
      const existingQuestions = [];
      const qBlocks = cleanText.split(/(?=(?:###|\*\*|##)?\s*(?:Quest[aã]o\s+\d+|Questão|\b\d+\.\s+|Q\d+[:\s]))/i);

      let theoryTextTotal = '';

      qBlocks.forEach((block, bIdx) => {
        if (!block || block.trim().length < 20) return;

        // Procura por alternativas A, B, C, D
        const optMatches = [];
        const optRegex = /(?:^|\n)\s*(?:\[\s*\]\s*)?(?:\(([A-E])\)|([A-E])[\)\.\-])\s*([^\n]+)/gi;
        let oMatch;
        while ((oMatch = optRegex.exec(block)) !== null) {
          const letter = (oMatch[1] || oMatch[2]).toUpperCase();
          const optText = (oMatch[3] || '').trim();
          optMatches.push({ letter, text: optText });
        }

        if (optMatches.length >= 3) {
          // Extrai o enunciado (texto antes da primeira alternativa)
          const firstOptPos = block.search(/(?:^|\n)\s*(?:\[\s*\]\s*)?(?:\(([A-E])\)|([A-E])[\)\.\-])/i);
          let promptRaw = firstOptPos > 0 ? block.substring(0, firstOptPos) : block;
          promptRaw = promptRaw
            .replace(/^(?:###|\*\*|##)?\s*(?:Quest[aã]o\s+\d+|Questão|\b\d+\.\s+|Q\d+[:\s])[:\s\-]*/i, '')
            .replace(/\*\*/g, '')
            .trim();

          const options = optMatches.slice(0, 4).map(o => o.text);
          const qNum = existingQuestions.length + 1;
          const correctIdx = (typeof gabaritoMap[qNum] === 'number') ? gabaritoMap[qNum] : 0;

          existingQuestions.push({
            source: 'reused',
            question: promptRaw || `Questão ${qNum} sobre ${cleanTitle}`,
            vignette: detectedDocVignette || (promptRaw.length > 120 ? promptRaw.substring(0, 100) + '...' : ''),
            options: options,
            correctIndex: correctIdx,
            explanation: `Gabarito oficial indicado no caderno de questões (Alternativa ${String.fromCharCode(65 + correctIdx)}).`,
            pearl: 'Fixação de conceito recorrente em provas.',
            flashcardFront: `O que preconiza a Questão ${qNum} sobre ${cleanTitle}?`,
            flashcardBack: `Alternativa correta: ${options[correctIdx] || 'Conforme gabarito.'}`,
            difficulty: 'intermediario'
          });
        } else {
          // Bloco sem alternativas: verifica se é texto didático/teórico (exclui cabeçalhos e gabarito)
          const lines = block.split('\n').filter(line => {
            const l = line.trim();
            if (l.length < 25) return false;
            if (l.startsWith('#')) return false;
            if (l.match(/^(?:Gabarito|Respostas?|Simulado|Caderno|Prova)/i)) return false;
            if (l.match(/^(?:Quest[aã]o\s*\d+[:\s\-–]*(?:Alternativa|Resposta)?\s*[A-E])/i)) return false;
            return true;
          });
          if (lines.length > 0) {
            theoryTextTotal += ' ' + lines.join(' ');
          }
        }
      });

      // 3. Busca por Questões Discursivas com Respostas/Gabarito (Estudos Dirigidos, E.D.s)
      const discursiveRegex = /(?:^|\n)\s*(?:Quest[aã]o\s*(\d+)|\b(\d+)[\.\)]|\bQ(\d+)[:\s\)])\s*([^\n\r]+?)(?:\n|\r|\s+)*(?:Resposta|Gabarito|Resp|R)[:\s\-–]*([^\n\r]+(?:\n(?!(?:Quest[aã]o|\b\d+[\.\)]|\bQ\d+[:\s\)]|#|\n\s*\n\s*\n))([^\n\r]+))*)/gi;
      let dMatch;
      while ((dMatch = discursiveRegex.exec(cleanText)) !== null) {
        const qNum = dMatch[1] || dMatch[2] || dMatch[3] || (existingQuestions.length + 1);
        let qPrompt = (dMatch[4] || '').trim();
        let qAnswer = (dMatch[5] || '').trim();

        if (qPrompt.length >= 10 && qAnswer.length >= 5) {
          // Evita duplicatas se já tiver sido capturada
          const isDup = existingQuestions.some(eq => eq.question && eq.question.includes(qPrompt.substring(0, 30)));
          if (!isDup) {
            const shortAns = qAnswer.length > 150 ? qAnswer.substring(0, 147) + '...' : qAnswer;
            const distractors = generateMedicalDistractorsForLocal(qPrompt, qAnswer, cleanTitle);
            const options = [shortAns, ...distractors.slice(0, 3)];

            existingQuestions.push({
              source: 'reused',
              question: qPrompt,
              vignette: detectedDocVignette || (qPrompt.length > 120 ? qPrompt.substring(0, 100) + '...' : ''),
              options: options,
              correctIndex: 0,
              explanation: qAnswer,
              pearl: `Fixação clínica: ${shortAns}`,
              flashcardFront: qPrompt,
              flashcardBack: qAnswer,
              difficulty: 'intermediario'
            });
          }
        }
      }

      const hasQuestions = existingQuestions.length > 0;
      const hasDidacticText = theoryTextTotal.trim().length > 250;

      let detectedType = 'text_only';
      if (hasQuestions && hasDidacticText) {
        detectedType = 'both';
      } else if (hasQuestions) {
        detectedType = 'questions_only';
      } else {
        detectedType = 'text_only';
      }

      const generatedFromText = [];

      // Se for text_only ou both, gera questões complementares a partir da teoria
      if (detectedType === 'text_only' || detectedType === 'both') {
        const genCount = detectedType === 'both' ? 3 : 5;
        for (let i = 0; i < genCount; i++) {
          const diff = i === 0 ? 'iniciante' : (i === 1 ? 'intermediario' : 'avancado');
          const mockQ = (typeof createMedicalQuestionObject === 'function')
            ? createMedicalQuestionObject(cleanTitle, targetSubj, i, { difficulty: diff })
            : {
                question: `A respeito de ${cleanTitle} no contexto de ${targetSubj}, assinale a conduta ou mecanismo correto:`,
                quizOptions: [
                  `Reconhecimento semiológico precoce e abordagem escalonada conforme gravidade.`,
                  `Intervenção cirúrgica imediata sem estratificação de risco propedêutico.`,
                  `Suspensão de todo suporte clínico antes da confirmação laboratorial.`,
                  `Aguardar evolução espontânea sem monitorização intensiva.`
                ],
                correctIndex: 0,
                explanation: `A abordagem de ${cleanTitle} exige reconhecimento precoce e seguimento de diretrizes clínicas do SUS/PCDT.`,
                tripartite: { pearl: `Conhecimento cardinal de ${cleanTitle} frequentemente cobrado no ENARE.` },
                flashcard: { back: `Abordagem escalonada e protocolo oficial para ${cleanTitle}.` }
              };

          generatedFromText.push({
            source: 'generated_from_text',
            question: mockQ.question,
            vignette: mockQ.vignette || '',
            options: mockQ.quizOptions,
            correctIndex: mockQ.correctIndex,
            explanation: mockQ.explanation,
            pearl: mockQ.tripartite?.pearl || '',
            flashcardFront: `O que caracteriza a abordagem clínica de ${cleanTitle}?`,
            flashcardBack: mockQ.flashcard?.back || mockQ.explanation,
            difficulty: diff
          });
        }
      }

      const allItems = [...existingQuestions, ...generatedFromText];
      return {
        detectedType: detectedType,
        detectedTypeDescription: detectedType === 'questions_only' 
          ? 'Banco de questões com alternativas reaproveitadas.' 
          : (detectedType === 'both' ? 'Material misto com teoria e questões de fixação.' : 'Material didático teórico transformado em questões.'),
        clinicalSubject: cleanTitle,
        reusedQuestionsCount: existingQuestions.length,
        generatedFromTextCount: generatedFromText.length,
        items: allItems
      };
    }

    function convertChatMessageToFlashcard(topic) {
      createCardFromChatMsg(topic);
      navigateTab('flashcards');
    }

    function convertChatMessageToEnareQuiz(topic) {
      createCardFromChatMsg(topic);
      navigateTab('quizzes');
    }

    function createCardFromChatMsg(topic) {
      const red = evaluateRedundancy(topic);
      const enareObj = createEnareQuestionObject(topic, 'Revisão do Chat', 0);
      enareObj.isRedundant = red.isRedundant;
      enareObj.redundancyScore = red.percentage;
      enareObj.matchedText = red.matchedText;

      sharedQuestionsBank.unshift(enareObj);
      renderSharedStudyItems();
      renderSceBars();
      updateSubjectFilterMenus();
      showToast('✅ Questão ENARE adicionada aos Flashcards e Quizzes!');
    }

