    var chatDriveMaterials = [];
    var currentReaderFontSize = 16; // 16px = 12pt (Padrão ABNT NBR 14724)

    function initChatDriveMaterials() {
      if (typeof sortChatDriveMaterialsInLearningOrder === 'function') {
        sortChatDriveMaterialsInLearningOrder();
      }
      renderChatDriveVerticalList();
      updateChatAttachedBar();
    }

    function toggleChatDriveDropdown() {
      const dd = document.getElementById('chatDriveDropdown');
      if (!dd) return;
      dd.classList.toggle('visible');
      const sMenu = document.getElementById('chatSubjectDropdownMenu');
      if (sMenu) sMenu.classList.remove('visible');
      renderChatDriveVerticalList();
    }

    function renderChatDriveVerticalList() {
      const container = document.getElementById('chatDriveVerticalList');
      if (!container) return;
      container.innerHTML = '';

      if (typeof sortChatDriveMaterialsInLearningOrder === 'function') {
        sortChatDriveMaterialsInLearningOrder();
      }

      if (chatDriveMaterials.length === 0) {
        container.innerHTML = `
          <div style="padding: 24px; text-align: center; color: var(--text-secondary); font-size: 13px;">
            Nenhum material no Drive. Faça novo upload ou sincronize uma pasta.
          </div>
        `;
        return;
      }

      chatDriveMaterials.forEach((file) => {
        const item = document.createElement('div');
        item.className = 'chat-drive-vertical-item' + (file.selected ? ' selected' : '');
        item.onclick = (e) => {
          if (e.target.tagName.toLowerCase() !== 'input') {
            toggleDriveFileCheck(file.id, !file.selected);
          }
        };

        item.innerHTML = `
          <input type="checkbox" ${file.selected ? 'checked' : ''} onchange="toggleDriveFileCheck('${file.id}', this.checked)">
          <div style="flex: 1; min-width: 0;">
            <div style="font-weight: 600; font-size: 13px; color: var(--text-primary); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;" title="${file.name}">
              ${file.isBook ? '📖' : '📄'} ${file.name}
            </div>
            <div style="display: flex; gap: 6px; align-items: center; margin-top: 4px; font-size: 11px; flex-wrap: wrap;">
              ${file.folderPath && file.folderPath !== '/' ? `<span style="background: rgba(0, 229, 255, 0.12); color: var(--neon); padding: 1px 5px; border-radius: 4px; font-size: 10px; font-weight: 600;">📁 ${file.folderPath}</span>` : ''}
              ${file.compressionStats ? `<span style="background: rgba(0, 255, 102, 0.12); color: #00ff66; border: 1px solid rgba(0, 255, 102, 0.25); padding: 1px 5px; border-radius: 4px; font-size: 10px; font-weight: 700;" title="Arquivo otimizado: de ${file.compressionStats.originalSizeMB.toFixed(1)}MB para ${file.compressionStats.compressedSizeKB}KB">⚡ -${file.compressionStats.reductionPercent}% (WebP+MD)</span>` : ''}
              ${file.learningOrder ? `<span style="background: rgba(100, 108, 255, 0.15); color: #8c9eff; border: 1px solid rgba(140, 158, 255, 0.3); padding: 1px 5px; border-radius: 4px; font-size: 10px; font-weight: 700;" title="${escapeHtml(file.pedagogicalRationale || file.pedagogicalPhaseName || '')}">${file.pedagogicalIcon || '🎯'} Passo ${file.learningOrder} • ${escapeHtml(file.pedagogicalPhaseName || '')}</span>` : ''}
              <span class="disease-tag">${file.disease || file.tag}</span>
              <span style="color: var(--text-secondary);">${file.sizeStr}</span>
              <span style="color: var(--text-muted); overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">• ${file.topic}</span>
            </div>
          </div>
          <div style="display: flex; gap: 5px; margin-left: 6px; flex-shrink: 0;">
            <button class="btn-outline-action" style="padding: 2px 7px; font-size: 10px; border-radius: 6px;" onclick="event.stopPropagation(); openAcademicReportForMaterial('${(file.id || file.name).replace(/'/g, "\\'")}', '${(file.subject || '').replace(/'/g, "\\'")}', '${file.name.replace(/'/g, "\\'")}')" title="Gerar relatório exclusivo deste PDF ou slide">📄 Relatório</button>
            <button class="btn-outline-action danger" style="padding: 2px 7px; font-size: 11px; border-radius: 6px;" onclick="event.stopPropagation(); deleteMaterialFromSubject('${(file.id || file.name).replace(/'/g, "\\'")}', '${(file.subject || '').replace(/'/g, "\\'")}')" title="Excluir este conteúdo da matéria">🗑️</button>
          </div>
        `;
        container.appendChild(item);
      });

      const selectedCount = chatDriveMaterials.filter(m => m.selected).length;
      const totalCount = chatDriveMaterials.length;
      
      const countLabel = document.getElementById('driveSelectedVerticalCount');
      if (countLabel) countLabel.textContent = `${selectedCount} de ${totalCount} selecionadas`;

      const allChk = document.getElementById('chkSelectAllDriveFiles');
      if (allChk) allChk.checked = (selectedCount === totalCount && totalCount > 0);

      const chatDriveCount = document.getElementById('chatDriveCount');
      if (chatDriveCount) chatDriveCount.textContent = selectedCount;
    }

    function toggleDriveFileCheck(id, checked) {
      const item = chatDriveMaterials.find(m => m.id === id);
      if (item) {
        item.selected = checked;
        saveChatDriveMaterials();
        renderChatDriveVerticalList();
        updateChatAttachedBar();
      }
    }

    function toggleSelectAllDriveFiles(checked) {
      chatDriveMaterials.forEach(m => { m.selected = checked; });
      saveChatDriveMaterials();
      renderChatDriveVerticalList();
      updateChatAttachedBar();
      showToast(checked ? 'Todas as aulas marcadas!' : 'Todas as aulas desmarcadas.');
    }

    async function deleteSelectedDriveFiles() {
      const toDelete = chatDriveMaterials.filter(m => m.selected);
      if (toDelete.length === 0) {
        showToast('Nenhum item marcado para eliminar.');
        return;
      }
      const count = toDelete.length;
      const confirmed = confirm(`Deseja realmente excluir os ${count} materiais selecionados do Drive?`);
      if (!confirmed) return;

      if (typeof MedTutorFirebaseService !== 'undefined' && typeof MedTutorFirebaseService.deleteMaterial === 'function') {
        for (const item of toDelete) {
          await MedTutorFirebaseService.deleteMaterial(item.id || item.name);
        }
      } else {
        chatDriveMaterials = chatDriveMaterials.filter(m => !m.selected);
      }
      saveChatDriveMaterials();
      if (typeof renderSlideSelectors === 'function') renderSlideSelectors();
      if (typeof renderChatDriveVerticalList === 'function') renderChatDriveVerticalList();
      if (typeof updateChatAttachedBar === 'function') updateChatAttachedBar();
      if (typeof renderCurriculumGrid === 'function') renderCurriculumGrid();
      if (typeof updateSubjectFilterMenus === 'function') updateSubjectFilterMenus();
      showToast(`🗑️ ${count} material(is) eliminado(s) com sucesso!`);
    }

    // RELATÓRIO DE ESTUDO DO DRIVE (CRITICAL: NÃO ELIMINA NENHUM ITEM)
    function generateDriveReport() {
      const totalFiles = chatDriveMaterials.length;
      if (totalFiles === 0) {
        showToast('Nenhum material disponível no Drive para gerar relatório.');
        return;
      }

      const selectedFiles = chatDriveMaterials.filter(m => m.selected);
      const diseases = [...new Set(chatDriveMaterials.map(m => m.disease || m.tag))];

      const flow = document.getElementById('chatFlow');
      const empty = document.getElementById('chatEmptyState');
      if (empty) empty.style.display = 'none';

      const reportBubble = document.createElement('div');
      reportBubble.className = 'chat-bubble tutor';
      reportBubble.style.maxWidth = '92%';

      const discTitle = currentScannedFolder ? (currentScannedFolder.disciplineKey || currentScannedFolder.title || 'Materiais Curriculares') : (chatDriveMaterials[0]?.subject || 'Materiais Curriculares');
      const discSub = currentScannedFolder?.sub || 'Sincronização & Análise Curricular';

      reportBubble.innerHTML = `
        <div class="tutor-header">
          <svg class="icon" viewBox="0 0 24 24"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><polyline points="14 2 14 8 20 8"/><line x1="16" y1="13" x2="8" y2="13"/><line x1="16" y1="17" x2="8" y2="17"/></svg>
          Relatório de Cobertura Curricular & Auditoria do Drive (Sem Exclusão)
        </div>
        <div style="background: rgba(0, 255, 102, 0.05); border: 1px solid rgba(0, 255, 102, 0.2); border-radius: 12px; padding: 14px; margin-top: 8px;">
          <div style="display: flex; justify-content: space-between; align-items: center; border-bottom: 1px solid var(--border); padding-bottom: 10px; margin-bottom: 10px;">
            <div>
              <strong style="font-size: 14px; color: var(--text-primary);">Auditoria Curricular: ${discTitle}</strong>
              <div style="font-size: 11px; color: var(--text-secondary); margin-top: 2px;">Google Drive: ${discSub}</div>
            </div>
            <span style="background: var(--neon); color: #000; font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 6px;">100% Preservado</span>
          </div>

          <div style="display: grid; grid-template-columns: repeat(3, 1fr); gap: 10px; margin-bottom: 14px;">
            <div style="background: var(--bg-surface); padding: 10px; border-radius: 8px; border: 1px solid var(--border); text-align: center;">
              <div style="font-size: 18px; font-weight: 800; color: var(--neon);">${totalFiles}</div>
              <div style="font-size: 11px; color: var(--text-secondary);">Materiais no Drive</div>
            </div>
            <div style="background: var(--bg-surface); padding: 10px; border-radius: 8px; border: 1px solid var(--border); text-align: center;">
              <div style="font-size: 18px; font-weight: 800; color: #60a5fa;">${diseases.length}</div>
              <div style="font-size: 11px; color: var(--text-secondary);">Afecções Mapeadas</div>
            </div>
            <div style="background: var(--bg-surface); padding: 10px; border-radius: 8px; border: 1px solid var(--border); text-align: center;">
              <div style="font-size: 18px; font-weight: 800; color: #f59e0b;">${selectedFiles.length}</div>
              <div style="font-size: 11px; color: var(--text-secondary);">Marcados p/ Leitura</div>
            </div>
          </div>

          <div style="font-size: 12px; font-weight: 700; color: var(--text-primary); margin-bottom: 6px;">
            Mapeamento dos Materiais por Doença e Conteúdo:
          </div>
          <div style="font-size: 12px; color: var(--text-secondary); line-height: 1.6;">
            ${chatDriveMaterials.map(m => `
              <div style="display: flex; justify-content: space-between; align-items: center; padding: 5px 0; border-bottom: 1px dashed var(--border);">
                <span>${m.isBook ? '📖' : '📄'} <strong>${m.name}</strong> <span style="color: var(--neon); font-size: 10px; margin-left: 4px;">[${m.disease || m.tag}]</span></span>
                <span style="font-size: 11px; color: var(--text-muted);">${m.sizeStr}</span>
              </div>
            `).join('')}
          </div>

          <div style="margin-top: 12px; padding: 10px; background: rgba(255,255,255,0.02); border-radius: 8px; font-size: 11px; color: var(--text-secondary); line-height: 1.5;">
            📌 <em>Garantia do Sistema: A emissão deste relatório de auditoria não altera nem elimina nenhum dos ${totalFiles} materiais da base. Todos permanecem disponíveis para estudo.</em>
          </div>

          <div style="display: flex; gap: 8px; margin-top: 12px; flex-wrap: wrap;">
            <button class="btn-outline-action primary" onclick="requestReadingMaterialProduction(false)">
              📖 Produzir Apostila de Leitura com Base no Relatório
            </button>
            <button class="btn-outline-action" onclick="navigateTab('flashcards')">
              🗂️ Ver Flashcards por Afecção Clínica
            </button>
          </div>
        </div>
      `;

      flow.appendChild(reportBubble);
      flow.scrollTop = flow.scrollHeight;
      toggleChatDriveDropdown();
      showToast('📊 Relatório de estudo gerado no chat (nenhum item foi excluído)!');
    }

    function removeChatDriveFile(id) {
      const item = chatDriveMaterials.find(m => m.id === id);
      if (item) {
        item.selected = false;
        renderChatDriveVerticalList();
        updateChatAttachedBar();
      }
    }

    function updateChatAttachedBar() {
      const selected = chatDriveMaterials.filter(m => m.selected);
      const bar = document.getElementById('chatAttachedBar');
      const chipsList = document.getElementById('chatAttachedChipsList');
      const countEl = document.getElementById('chatDriveCount');

      if (countEl) countEl.textContent = selected.length;

      if (selected.length === 0) {
        if (bar) bar.style.display = 'none';
        return;
      }

      if (bar) bar.style.display = 'flex';
      if (chipsList) {
        chipsList.innerHTML = selected.map(m => `
          <div class="chat-file-chip" title="${m.name}">
            <span>${m.name.length > 25 ? m.name.slice(0, 23) + '...' : m.name}</span>
            <button class="chip-remove" onclick="removeChatDriveFile('${m.id}')" title="Desmarcar">×</button>
          </div>
        `).join('');
      }
    }

    function selectAllDriveAulasForReading(select) {
      chatDriveMaterials.forEach(m => {
        if (select) {
          m.selected = !m.isBook; // Seleciona todas as 7 aulas, preservando o livro extenso Azulay desmarcado
        } else {
          m.selected = false;
        }
      });
      renderChatDriveVerticalList();
      updateChatAttachedBar();
      showToast(select ? '✅ Todas as 7 aulas marcadas para leitura!' : 'Materiais do Drive desmarcados.');
    }

    function clearChatDriveSelection() {
      selectAllDriveAulasForReading(false);
    }

    function produceReadingFromDriveModal() {
      importDriveEligibleFiles();
    }

    // 12. DROPDOWNS DE MATÉRIA & AFECÇÕES CLÍNICAS (CHAT & FLASHCARDS)
    function toggleFcSubjectDropdown() {
      const menu = document.getElementById('fcSubjectDropdownMenu');
      if (menu) menu.classList.toggle('visible');
    }

    function toggleChatSubjectDropdown() {
      const menu = document.getElementById('chatSubjectDropdownMenu');
      if (menu) {
        menu.classList.toggle('visible');
        const driveDd = document.getElementById('chatDriveDropdown');
        if (driveDd) driveDd.classList.remove('visible');
      }
    }

    function getAvailableDiseases() {
      const diseases = new Set();
      sharedQuestionsBank.forEach(q => {
        if ((!currentStudySubject || q.subject === currentStudySubject) && q.disease) {
          diseases.add(q.disease);
        }
      });
      chatDriveMaterials.forEach(m => {
        if ((!currentStudySubject || m.subject === currentStudySubject) && m.disease) {
          diseases.add(m.disease);
        }
      });
      return Array.from(diseases);
    }

    function updateSubjectFilterMenus() {
      const diseases = getAvailableDiseases();
      const currentDiscipline = (currentScannedFolder && currentScannedFolder.disciplineKey) ||
        (chatDriveMaterials.length > 0 && chatDriveMaterials[0].subject ? chatDriveMaterials[0].subject : null) ||
        (sharedQuestionsBank.length > 0 && sharedQuestionsBank[0].subject ? sharedQuestionsBank[0].subject : null);

      // Atualiza o indicador de matéria no Chat
      const chatLabel = document.getElementById('chatSubjectCurrentName');
      if (chatLabel) {
        if (!currentDiscipline && diseases.length === 0) {
          chatLabel.textContent = 'Geral (Aguardando Upload)';
        } else if (chatLabel.textContent === 'Geral (Aguardando Upload)' || chatLabel.textContent.includes('Integração de Sistemas')) {
          chatLabel.textContent = currentDiscipline || 'Geral (Aguardando Upload)';
        }
      }

      // 1. Menu de Flashcards
      const fcMenu = document.getElementById('fcSubjectDropdownMenu');
      if (fcMenu) {
        if (diseases.length === 0) {
          fcMenu.innerHTML = `
            <div class="dropdown-item active" onclick="setFcDiseaseFilter('all')">
              <strong>Todas as Doenças</strong> (Aguardando uploads)
            </div>
          `;
        } else {
          fcMenu.innerHTML = `
            <div class="dropdown-item ${currentDiseaseFilter === 'all' ? 'active' : ''}" onclick="setFcDiseaseFilter('all')">
              <strong>Todas as Doenças</strong> (Todos os Cards)
            </div>
            ${diseases.map(d => `
              <div class="dropdown-item ${currentDiseaseFilter === d ? 'active' : ''}" onclick="setFcDiseaseFilter('${d.replace(/'/g, "\\'")}')">
                🔬 ${d}
              </div>
            `).join('')}
          `;
        }
      }

      // 2. Menu do Chat
      const chatMenu = document.getElementById('chatSubjectDropdownMenu');
      if (chatMenu) {
        if (diseases.length === 0) {
          chatMenu.innerHTML = `
            <div class="dropdown-item active" onclick="setChatDiseasePrompt('all')">
              <strong>Geral</strong> (Aguardando upload de materiais)
            </div>
          `;
        } else {
          chatMenu.innerHTML = `
            <div class="dropdown-item" onclick="setChatDiseasePrompt('all')">
              <strong>Todas as Doenças</strong> (${currentDiscipline || 'Visão Geral da Disciplina'})
            </div>
            ${diseases.map(d => `
              <div class="dropdown-item" onclick="setChatDiseasePrompt('${d.replace(/'/g, "\\'")}')">
                🔬 ${d}
              </div>
            `).join('')}
          `;
        }
      }
    }

    function setFcDiseaseFilter(disease) {
      currentDiseaseFilter = disease;
      const label = document.getElementById('fcCurrentFilterLabel');
      if (label) {
        label.textContent = disease === 'all' ? 'Todas as Doenças' : disease;
      }
      const menu = document.getElementById('fcSubjectDropdownMenu');
      if (menu) menu.classList.remove('visible');
      currentCardIndex = 0;
      renderSharedStudyItems();
      updateSubjectFilterMenus();
      showToast(disease === 'all' ? 'Exibindo todos os cards.' : `Filtrado por: ${disease}`);
    }

    function setChatDiseasePrompt(disease) {
      const menu = document.getElementById('chatSubjectDropdownMenu');
      if (menu) menu.classList.remove('visible');
      const label = document.getElementById('chatSubjectCurrentName');
      const currentDiscipline = (currentScannedFolder && currentScannedFolder.disciplineKey) ||
        (chatDriveMaterials.length > 0 && chatDriveMaterials[0].subject ? chatDriveMaterials[0].subject : null) ||
        (sharedQuestionsBank.length > 0 && sharedQuestionsBank[0].subject ? sharedQuestionsBank[0].subject : null);

      if (label) {
        if (disease === 'all') {
          label.textContent = currentDiscipline || 'Geral (Aguardando Upload)';
        } else {
          label.textContent = currentDiscipline ? `${currentDiscipline.split('(')[0].trim()} • ${disease}` : `Disciplina • ${disease}`;
        }
      }
      if (disease !== 'all') {
        quickPrompt(`Quais os pontos-chave diagnósticos, lesões elementares e conduta terapêutica em ${disease}?`);
      } else {
        if (!currentDiscipline) {
          quickPrompt(`Como o tutor inteligente organiza o aprendizado e correlaciona as diretrizes clínicas a partir dos materiais enviados?`);
        } else {
          quickPrompt(`Apresente uma visão geral dos principais tópicos clínicos e diretrizes da disciplina ${currentDiscipline}.`);
        }
      }
    }

    // Fechar dropdowns ao clicar fora
    window.addEventListener('click', (e) => {
      if (!e.target.closest('#fcSubjectDropdownBtn') && !e.target.closest('#fcSubjectDropdownMenu')) {
        const fcMenu = document.getElementById('fcSubjectDropdownMenu');
        if (fcMenu) fcMenu.classList.remove('visible');
      }
      if (!e.target.closest('#fcStudyMoreMenu') && !e.target.closest('[onclick*="toggleStudyMoreOptions(\'fc\')"]')) {
        const m = document.getElementById('fcStudyMoreMenu');
        if (m) m.classList.remove('visible');
      }
      if (!e.target.closest('#qzStudyMoreMenu') && !e.target.closest('[onclick*="toggleStudyMoreOptions(\'qz\')"]')) {
        const m = document.getElementById('qzStudyMoreMenu');
        if (m) m.classList.remove('visible');
      }
    });

    // GERAÇÃO DO MATERIAL COMPLETO DE ESTUDO PARA LEITURA
    function requestReadingMaterialProduction(includeUserBubble = true) {
      let selected = chatDriveMaterials.filter(m => m.selected);
      if (selected.length === 0) {
        selectAllDriveAulasForReading(true);
        selected = chatDriveMaterials.filter(m => m.selected);
      }

      const flow = document.getElementById('chatFlow');
      const empty = document.getElementById('chatEmptyState');
      if (empty) empty.style.display = 'none';

      // 1. Bolha do usuário solicitando a leitura (se solicitado diretamente)
      if (includeUserBubble) {
        const userBubble = document.createElement('div');
        userBubble.className = 'chat-bubble user';
        userBubble.innerHTML = `
          <div style="font-weight: 600; margin-bottom: 4px;">📖 Solicitação de Material de Estudo para Leitura:</div>
          <div>Por favor, produza um roteiro/apostila didática de leitura médica aprofundado com base nos <strong>${selected.length} materiais marcados do Drive</strong>:</div>
          <div style="font-size: 11px; color: rgba(255,255,255,0.7); margin-top: 4px; line-height: 1.4;">
            ${selected.map(s => `• ${s.name}`).join('<br>')}
          </div>
        `;
        flow.appendChild(userBubble);
        flow.scrollTop = flow.scrollHeight;
      }

      // 2. Bolha do Tutor com o Material Estruturado de Leitura
      setTimeout(() => {
        const tutorBubble = document.createElement('div');
        tutorBubble.className = 'chat-bubble tutor';
        tutorBubble.style.maxWidth = '94%';

        const disciplineName = currentScannedFolder ? (currentScannedFolder.disciplineKey || 'Clínica Médica') : (selected[0]?.subject || 'Clínica Médica');
        const readingDoc = generateReadingDocumentHtml(selected, disciplineName, '', '');

        tutorBubble.innerHTML = `
          <div class="tutor-header">
            <svg class="icon" viewBox="0 0 24 24"><path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"/><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"/></svg>
            Material de Leitura Gerado a Partir do Google Drive
          </div>
          ${readingDoc.fullHtml}
        `;

        flow.appendChild(tutorBubble);
        flow.scrollTop = flow.scrollHeight;
        showToast('📖 Material de Estudo para Leitura gerado com sucesso!');

        if (typeof AppExpenseTracker !== 'undefined') {
          AppExpenseTracker.recordAction({
            actionName: `Síntese Didática de Leitura (${selected.length} materiais)`,
            isLocal: true
          });
        }
      }, 500);
    }

    // MODAL DE LEITURA FOCADA
    function openReaderModalFromCard(btn) {
      const modal = document.getElementById('readerModal');
      const content = document.getElementById('readerModalContent');
      if (!modal || !content) return;

      let card = null;
      if (btn && btn.closest) card = btn.closest('.reading-doc-card');
      if (!card) card = document.querySelector('.reading-doc-card');
      if (card) {
        const clone = card.cloneNode(true);
        const actions = clone.querySelector('.doc-actions-row');
        if (actions) actions.remove();
        content.innerHTML = clone.innerHTML;
      }
      modal.classList.add('active');
    }

    function changeReaderFontSize(delta) {
      currentReaderFontSize = Math.min(24, Math.max(11, currentReaderFontSize + delta));
      const content = document.getElementById('readerModalContent');
      if (content) {
        content.style.fontSize = currentReaderFontSize + 'px';
      }
    }

    function copyReaderModalText() {
      const content = document.getElementById('readerModalContent');
      if (!content) return;
      navigator.clipboard.writeText(content.innerText).then(() => {
        showToast('📋 Conteúdo da apostila copiado para a área de transferência!');
      }).catch(() => {
        showToast('Texto copiado com sucesso.');
      });
    }

    function copyReadingDocText(btn) {
      let card = null;
      if (btn && btn.closest) card = btn.closest('.reading-doc-card');
      if (!card) card = document.querySelector('.reading-doc-card');
      if (!card) return;
      navigator.clipboard.writeText(card.innerText).then(() => {
        showToast('📋 Material de leitura copiado com sucesso!');
      }).catch(() => {
        showToast('Texto copiado.');
      });
    }

    function extractFlashcardsFromReadingDoc() {
      const q = 'Quais são os sinais patognomônicos obtidos na curetagem de Brocq na Psoríase e no exame do Líquen Plano?';
      const red = evaluateRedundancy(q);
      sharedQuestionsBank.unshift({
        id: 'read-fc-' + Date.now(),
        subject: 'Dermatologia (Leitura)',
        question: q,
        answer: 'Na Psoríase: Sinal da vela (escamas estratificadas), Sinal da película de Duncan-Dulck e Sinal de Auspitz (orvalho sangrento). No Líquen Plano: Pápulas violáceas poligonais pruriginosas com Estrias de Wickham.',
        quizOptions: [
          'Sinal de Auspitz (orvalho sangrento) na Psoríase; Estrias de Wickham no Líquen Plano.',
          'Sinal de Nikolsky na Psoríase e pústulas no Líquen Plano.',
          'Ambos apresentam comedões abertos e vesículas herpéticas.',
          'Ausência de escamas ou linhas em ambas as patologias.'
        ],
        correctIndex: 0,
        isRedundant: red.isRedundant,
        redundancyScore: red.percentage,
        matchedText: red.matchedText,
        isStarred: false
      });
      renderSharedStudyItems();
      showToast('🗂️ Flashcard extraído do material de leitura e adicionado ao seu deck!');
    }

    function extractQuizzesFromReadingDoc() {
      const q = 'Diferencial de Eczemas: Qual a topografia clássica da Dermatite Atópica no lactente versus no adulto?';
      const red = evaluateRedundancy(q);
      sharedQuestionsBank.unshift({
        id: 'read-qz-' + Date.now(),
        subject: 'Dermatologia (Leitura)',
        question: q,
        answer: 'No lactente acomete face (malares poupando região perioral) e faces extensoras; no adulto predomina em dobras flexurais (fossas cubitais e poplíteas) com liquenificação crônica.',
        quizOptions: [
          'No lactente acomete exclusivamente dobras flexurais e no adulto a face.',
          'No lactente acomete malares poupando perioral e áreas extensoras; no adulto predomina em dobras flexurais.',
          'Ambos apresentam a mesma distribuição sem variação etária.',
          'Dermatite atópica não acomete a infância.'
        ],
        correctIndex: 1,
        isRedundant: red.isRedundant,
        redundancyScore: red.percentage,
        matchedText: red.matchedText,
        isStarred: false
      });
      renderSharedStudyItems();
      showToast('📝 Novo caso/quiz extraído para o seu simulado!');
    }

    // 12. CONTROLE DE AMBIENTE: ZERAR TUDO (HOT RELOAD) & RESTAURAR DEMO
    function confirmResetAllUploadedData() {
      closeModals();
      const modal = document.getElementById('resetConfirmModal');
      if (modal) modal.style.display = 'flex';
    }

    function executeResetAllUploadedData(forceReload = false) {
      closeModals();

      try {
        localStorage.setItem('medtutor_reset_clean', 'true');
        localStorage.removeItem('medtutor_saved_curriculum');
        localStorage.removeItem('medtutor_saved_drive_url');
        localStorage.removeItem('medtutor_chat_materials');
        localStorage.removeItem('medtutor_custom_questions');
        localStorage.removeItem('medtutor_shared_questions_v2');
      } catch (e) {}

      // 1. Limpar materiais do Google Drive
      chatDriveMaterials = [];
      scannedDriveFiles = [];
      currentScannedFolder = null;
      driveSearchQuery = '';
      pendingUploadMaterial = null;

      // 2. Limpar questões e flashcards
      sharedQuestionsBank = [];
      subjectGenerationStatus = {};
      currentStudySubject = '';
      currentCardIndex = 0;
      currentDiseaseFilter = 'all';

      // 3. Limpar ementa universitária
      universityCurriculum = [];
      if (typeof expandedCurriculumPeriods !== 'undefined') expandedCurriculumPeriods.clear();
      const currGrid = document.getElementById('curriculumGrid');
      const currHeader = document.getElementById('curriculumHeaderBar');
      const currEmpty = document.getElementById('curriculumEmptyState');
      if (currGrid) currGrid.style.display = 'none';
      if (currHeader) currHeader.style.display = 'none';
      if (currEmpty) currEmpty.style.display = 'flex';

      // 4. Limpar roteiro do Waze / SCE
      studyRouteSchedule = [];

      // 5. Limpar todos os inputs de arquivos e textos
      const inputIds = [
        'materialFileInput',
        'syllabusFileInput',
        'inlineDriveFileInput',
        'materialTextInput',
        'syllabusTextInput',
        'driveUrlInput',
        'drivePastedFilesInput',
        'inlineDrivePasteInput',
        'driveSearchFilter'
      ];
      inputIds.forEach(id => {
        const el = document.getElementById(id);
        if (el) el.value = '';
      });

      // 6. Ocultar containers do modal do Drive
      const driveResults = document.getElementById('driveResultsContainer');
      const driveFallback = document.getElementById('driveAuthFallbackContainer');
      const driveProgress = document.getElementById('driveScanProgress');
      if (driveResults) driveResults.style.display = 'none';
      if (driveFallback) driveFallback.style.display = 'none';
      if (driveProgress) driveProgress.style.display = 'none';

      // 7. Resetar fluxo do Chat para estado inicial limpo
      const chatFlow = document.getElementById('chatFlow');
      if (chatFlow) {
        chatFlow.innerHTML = `
          <div class="empty-state" id="chatEmptyState">
            <div class="empty-state-icon">
              <svg class="icon" viewBox="0 0 24 24"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg>
            </div>
            <h3>Ambiente Zerado & Pronto para Novos Testes</h3>
            <p>Todos os uploads e materiais anteriores foram zerados com sucesso. Carregue um novo material de aula ou conecte outra pasta do Google Drive.</p>
            <div style="display: flex; gap: 8px; flex-wrap: wrap; justify-content: center; margin-top: 10px;">
              <button class="btn-outline-action primary" onclick="openUploadMaterialModal()">
                <svg class="icon" viewBox="0 0 24 24"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                + Upload de Material de Aula
              </button>
              <button class="btn-outline-action" onclick="openDriveModal()">
                <svg class="icon" viewBox="0 0 24 24"><path d="M22 19a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h5l2 3h9a2 2 0 0 1 2 2z"/></svg>
                Conectar Pasta do Drive
              </button>
            </div>
          </div>
        `;
      }

      // 8. Limpar rótulos fixos e títulos para estado limpo
      const subLabel = document.getElementById('chatSubjectCurrentName');
      if (subLabel) subLabel.textContent = 'Geral (Aguardando Upload)';
      const fcLabel = document.getElementById('fcCurrentFilterLabel');
      if (fcLabel) fcLabel.textContent = 'Todas as Doenças';
      const folderTitle = document.getElementById('driveFolderTitleDisplay');
      if (folderTitle) folderTitle.textContent = 'DISCIPLINA: Nenhuma Pasta Conectada';
      const readerSub = document.getElementById('readerModalSubtitle');
      if (readerSub) readerSub.textContent = 'Material de Leitura Médica';
      const countEl = document.getElementById('chatDriveCount');
      if (countEl) countEl.textContent = '0';
      const manualInput = document.getElementById('manualDirectionInput');
      if (manualInput) manualInput.value = '';

      // 9. Atualizar todas as telas e componentes visuais
      renderChatDriveVerticalList();
      updateChatAttachedBar();
      updateSubjectFilterMenus();
      renderSharedStudyItems();
      renderSceBars();
      renderSceTimeline();

      if (forceReload) {
        showToast('🔄 Recarregando com ambiente zerado...');
        setTimeout(() => {
          window.location.reload();
        }, 350);
      } else {
        showToast('🧹 Todos os uploads foram zerados! Base 100% limpa para novos testes.');
      }
    }

    function restoreDemoData() {
      closeModals();
      try {
        localStorage.removeItem('medtutor_reset_clean');
      } catch (e) {}

      chatDriveMaterials = JSON.parse(JSON.stringify(DEFAULT_DRIVE_FOLDER_FILES));
      sharedQuestionsBank = JSON.parse(JSON.stringify(INITIAL_DEMO_QUESTIONS));
      studyRouteSchedule = [
        { day: 'Hoje', date: 'Hoje', topic: 'Dermatologia: Lesões Elementares e Semiologia Cutânea', subject: 'Sistemas Humanos 2', minutes: 30, status: 'scheduled' },
        { day: 'Amanhã', date: 'Amanhã', topic: 'Dermatologia: Psoríase, Auspitz e Líquen Plano', subject: 'Sistemas Humanos 2', minutes: 35, status: 'scheduled' },
        { day: 'Quarta-feira', date: '09/Set', topic: 'Eczemas: Dermatite Atópica vs Seborreica', subject: 'Sistemas Humanos 2', minutes: 25, status: 'delayed' }
      ];
      universityCurriculum = [];
      currentStudySubject = 'Integração de Sistemas Humanos 2 (Dermatologia)';
      subjectGenerationStatus = {
        'Integração de Sistemas Humanos 2 (Dermatologia)': {
          status: 'ready',
          materialsCount: 8,
          questionsCount: 5
        }
      };
      currentCardIndex = 0;
      currentDiseaseFilter = 'all';

      const subLabel = document.getElementById('chatSubjectCurrentName');
      if (subLabel) subLabel.textContent = 'Integração de Sistemas Humanos 2 (Dermatologia)';
      const folderTitle = document.getElementById('driveFolderTitleDisplay');
      if (folderTitle) folderTitle.textContent = 'DISCIPLINA: Integração de sistemas humanos 2';
      const readerSub = document.getElementById('readerModalSubtitle');
      if (readerSub) readerSub.textContent = 'Integração de Sistemas Humanos 2 • Módulo Dermatologia';

      initChatDriveMaterials();
      renderSharedStudyItems();
      renderSceBars();
      renderSceTimeline();
      updateSubjectFilterMenus();
      renderCurriculumGrid();

      if (typeof MedTutorFirebaseService !== 'undefined') {
        MedTutorFirebaseService.saveCurriculum(universityCurriculum);
        MedTutorFirebaseService.saveAllMaterials(chatDriveMaterials);
        MedTutorFirebaseService.saveAllQuestions(sharedQuestionsBank);
      }

      showToast('✨ Demonstração padrão restaurada e sincronizada na nuvem!');
    }

    // Inicialização ao carregar a página (respeita o estado de reset ou ementa salva)
    if (localStorage.getItem('medtutor_reset_clean') === 'true') {
      chatDriveMaterials = [];
      sharedQuestionsBank = [];
      studyRouteSchedule = [];
      subjectGenerationStatus = {};
      currentStudySubject = '';
      universityCurriculum = [];
      currentScannedFolder = null;
      const subLabel = document.getElementById('chatSubjectCurrentName');
      if (subLabel) subLabel.textContent = 'Geral (Aguardando Upload)';
      const folderTitle = document.getElementById('driveFolderTitleDisplay');
      if (folderTitle) folderTitle.textContent = 'DISCIPLINA: Nenhuma Pasta Conectada';
      const readerSub = document.getElementById('readerModalSubtitle');
      if (readerSub) readerSub.textContent = 'Material de Leitura Médica';
      const countEl = document.getElementById('chatDriveCount');
      if (countEl) countEl.textContent = '0';
    } else {
      loadSharedQuestionsBank();
      loadChatDriveMaterials();
      if (!savedCurriculum && sharedQuestionsBank.length === 0 && chatDriveMaterials.length === 0) {
        chatDriveMaterials = [];
        studyRouteSchedule = [];
        subjectGenerationStatus = {};
        currentStudySubject = '';
        universityCurriculum = [];
        currentScannedFolder = null;
        const subLabel = document.getElementById('chatSubjectCurrentName');
        if (subLabel) subLabel.textContent = 'Geral (Aguardando Upload)';
        const folderTitle = document.getElementById('driveFolderTitleDisplay');
        if (folderTitle) folderTitle.textContent = 'DISCIPLINA: Nenhuma Pasta Conectada';
      } else if (sharedQuestionsBank.length > 0 && !currentStudySubject) {
        currentStudySubject = sharedQuestionsBank[0].subject || '';
        const subLabel = document.getElementById('chatSubjectCurrentName');
        if (subLabel && currentStudySubject) subLabel.textContent = currentStudySubject;
      } else if (chatDriveMaterials.length > 0 && !currentStudySubject) {
        currentStudySubject = chatDriveMaterials[0].subject || '';
        const subLabel = document.getElementById('chatSubjectCurrentName');
        if (subLabel && currentStudySubject) subLabel.textContent = currentStudySubject;
      }
    }
    initChatDriveMaterials();
    initChatSessions();
    renderSharedStudyItems();
    renderSceBars();
    renderSceTimeline();
    updateSubjectFilterMenus();
    renderCurriculumGrid();
    updateGeminiKeyBadge();
    setupMobileChatDrawer();
    loadDoubtsNotebook();
    restoreStudyNavigationState();

    // Inicialização do Serviço de Autenticação e Persistência Dual-Layer (Zero Perda de F5)
    if (typeof MedTutorAuthService !== 'undefined') {
      MedTutorAuthService.init();
    }
    if (typeof MedTutorFirebaseService !== 'undefined') {
      MedTutorFirebaseService.loadAllDataFromPersistence();
    }

    if (typeof window !== 'undefined') {
      window.MedTutorAuthService = MedTutorAuthService;
      window.MedTutorFirebaseService = MedTutorFirebaseService;
      window.MedTutorLocalDB = MedTutorLocalDB;
    }
